# -*- coding: utf-8 -*-
# 第 10 批（F1）：海洋污染防治法（112/05/31）第 1 條至第 34 條
# ※ 四個選項刻意寫成相近長度。
OP = "ENV-14"
Q = [
# ---------- 第一章 總則 ----------
(OP,"第1條",1,"海污法-立法目的",
 "制定海洋污染防治法之立法目的為何？",
 ["為防治海洋污染，保護海洋環境，維護海洋生態，確保國民健康及永續利用海洋資源","為開發海洋礦產，促進海運發展，維護漁業秩序，確保船舶航行安全及擴大海域使用","為劃定海域界線，管理海岸土地，推動海埔地開發，確保國土保安及增加財政收入","為整合海域執法，統一海事裁判，強化船員訓練，確保航業競爭力及國際貿易接軌"],"a",
 "第1條：為防治海洋污染，保護海洋環境，維護海洋生態，確保國民健康及永續利用海洋資源，特制定本法。第2條進一步界定本法適用之海域範圍，第3條定明主管機關為海洋委員會、執行機關為海岸巡防機關。",
 "What is the stated legislative purpose of the Marine Pollution Control Act?",
 ["To prevent marine pollution, protect the marine environment, maintain marine ecology, safeguard public health and sustainably use marine resources","To develop marine minerals, promote the shipping industry, maintain order in fisheries, ensure vessel navigation safety and expand use of sea areas","To delimit sea boundaries, administer coastal land, promote reclaimed land development, secure national territory and increase fiscal revenue","To integrate maritime enforcement, unify maritime adjudication, strengthen crew training, ensure shipping competitiveness and trade integration"],
 "Article 1."),

(OP,"第2條",2,"海污法-適用範圍",
 "本法適用之海域範圍為何？在該範圍外排放有害物質而造成範圍內污染時如何處理？",
 ["適用於中華民國管轄之潮間帶、內水、領海、鄰接區、專屬經濟海域及大陸礁層上覆水域；於該範圍外排放有害物質致範圍內污染者，亦適用本法","僅適用於中華民國管轄之內水、領海及鄰接區；於該範圍外排放有害物質致範圍內污染者，改依國際公約處理，不適用本法之規定","適用於中華民國管轄之潮間帶、內水及領海三者；專屬經濟海域與大陸礁層上覆水域之污染，一律改依海洋基本法之規定處理","適用於中華民國管轄之全部海域及其毗鄰陸域；於該範圍外排放有害物質者，不論是否造成範圍內污染，均一律適用本法"],"a",
 "第2條第1項：本法適用於中華民國管轄之潮間帶、內水、領海、鄰接區、專屬經濟海域及大陸礁層上覆水域。第2項：於前項範圍外海域排放有害物質，致造成前項範圍內污染者，亦適用本法。第14條另規定與該水域相連之陸域及地面水體，其轄管機關應採措施防止廢棄物污染海洋。",
 "What sea areas does the Act cover, and what if hazardous substances are discharged outside them but cause pollution inside?",
 ["The intertidal zone, internal waters, territorial sea, contiguous zone, EEZ and waters above the continental shelf under ROC jurisdiction; discharges outside that cause pollution inside are also covered","Only the internal waters, the territorial sea and the contiguous zone under ROC jurisdiction; discharges outside that cause pollution inside are handled under international conventions instead","Only the intertidal zone, internal waters and the territorial sea; pollution of the EEZ and waters above the continental shelf is handled under the Ocean Basic Act instead","All sea areas under ROC jurisdiction and adjacent land; discharges outside are always covered whether or not they cause any pollution inside the covered area"],
 "Article 2."),

(OP,"第3條",2,"海污法-主管機關",
 "本法所稱主管機關、執行機關及協助執行機關分別指何者？地方主管機關之海域管轄範圍由誰劃定？",
 ["中央為海洋委員會，地方為直轄市、縣（市）政府；執行機關指海岸巡防機關；協助執行機關指協助取締蒐證移送之軍事、海關等機關；海域管轄範圍由中央主管機關劃定","中央為環境部，地方為直轄市、縣（市）政府；執行機關指各地航政機關；協助執行機關指協助取締蒐證移送之警察、消防等機關；海域管轄範圍由行政院逕行劃定","中央為交通部，地方為直轄市、縣（市）政府；執行機關指港口管理機關；協助執行機關指協助取締蒐證移送之漁業、水利等機關；海域管轄範圍由內政部會商劃定","中央為內政部，地方為直轄市、縣（市）政府；執行機關指海洋保育署；協助執行機關指協助取締蒐證移送之國防、外交等機關；海域管轄範圍由各地方政府自行劃定"],"a",
 "第3條：中央主管機關為海洋委員會，直轄市、縣（市）為各該政府；執行機關指海岸巡防機關；協助執行機關指協助辦理取締、蒐證、移送等事項之軍事、海關或其他相關機關；直轄市、縣（市）主管機關之海域管轄範圍，由中央主管機關劃定。第5條並定明取締、蒐證、移送由執行機關辦理。",
 "Who are the competent authority, the enforcement authority and the assisting authorities, and who delimits local sea jurisdiction?",
 ["Central: the Ocean Affairs Council; local: municipal and county governments; enforcement: the coast guard; assisting: military, customs and other agencies aiding interception, evidence-gathering and referral; sea jurisdiction delimited by the central authority","Central: the Ministry of Environment; local: municipal and county governments; enforcement: maritime administration offices; assisting: police, fire and other agencies aiding interception and referral; sea jurisdiction delimited by the Executive Yuan","Central: the Ministry of Transportation; local: municipal and county governments; enforcement: port authorities; assisting: fisheries, water and other agencies aiding interception and referral; sea jurisdiction delimited by the Ministry of the Interior","Central: the Ministry of the Interior; local: municipal and county governments; enforcement: the Ocean Conservation Administration; assisting: defense, foreign affairs and other agencies aiding referral; sea jurisdiction delimited by each local government"],
 "Article 3."),

(OP,"第4條",3,"海污法-用詞定義",
 "本法用詞定義中，有害物質、油及海洋環境品質標準分別所指為何？",
 ["有害物質指依聯合國國際海事組織所定國際海運危險品章程或符合防止船舶污染國際公約附錄三所述之物質；油指原油、重油、潤滑油、輕油、煤油、揮發油或其他公告之油及含油混合物；海洋環境品質標準指基於國家整體海洋環境保護目的所定之目標值","有害物質指經中央主管機關公告之毒性化學物質及關注化學物質；油僅指原油及重油二類，不含潤滑油、輕油、煤油與含油之混合物；海洋環境品質標準指為達成管制目的所定之分區、分階段目標值，由地方主管機關訂定並公告實施","有害物質指經環境部依廢棄物清理法公告之有害事業廢棄物；油指船舶燃油及其殘油，不含揮發油及輕油；海洋環境品質標準指各海域工程開發時應個別承諾之排放上限值，由目的事業主管機關逐案核定後公告","有害物質指依國際海洋法公約附件所列之放射性物質及重金屬；油指經濟部公告之石化產品及其原料；海洋環境品質標準指海域環境監測站設置之數量基準與採樣分析方法，由各港口管理機關擬訂報請核定"],"a",
 "第4條第1、3、4款：有害物質指依聯合國國際海事組織所定國際海運危險品章程或符合防止船舶污染國際公約附錄三所述之物質；油指原油、重油、潤滑油、輕油、煤油、揮發油或其他經中央主管機關公告之油及含油之混合物；海洋環境品質標準指基於國家整體海洋環境保護目的所定之目標值。第7款另定海洋環境管制標準指為達成品質標準所定分區、分階段之目標值，第8條為其訂定依據。",
 "How does the Act define hazardous substances, oil, and marine environment quality standards?",
 ["Hazardous substances: those in the IMO dangerous goods code or MARPOL Annex III; oil: crude, heavy, lubricating, light, kerosene, volatile oil and other announced oils and oily mixtures; quality standards: target values set for overall national marine protection","Hazardous substances: toxic and concerned chemicals announced by the central authority; oil: only crude and heavy oil, excluding lubricants, kerosene and oily mixtures; quality standards: zoned, phased target values set and announced by local authorities","Hazardous substances: hazardous industrial waste announced under the Waste Disposal Act; oil: bunker fuel and its residues only, excluding volatile and light oil; quality standards: case-by-case discharge caps pledged for each marine works project","Hazardous substances: radioactive materials and heavy metals listed in UNCLOS annexes; oil: petrochemical products announced by the economics ministry; quality standards: criteria for the number of monitoring stations and sampling methods"],
 "Article 4, subparagraphs 1, 3 and 4."),

(OP,"第4條",3,"海污法-用詞定義",
 "本法所稱海域工程、海洋設施及排洩，其定義為何？",
 ["海域工程指在本法適用海域內從事之探勘、開採、輸送、興建、敷設、修繕、抽砂、浚渫、打撈、掩埋、填土、養灘、發電或其他工程；海洋設施指海域工程所設置之人工結構物；排洩指排放、溢出、洩漏廢（污）水、油、廢棄物或有害物質等","海域工程指在領海範圍內從事之填海造地及港灣興建工程，不含抽砂、浚渫與養灘；海洋設施指船舶及航空器以外之一切浮動載具；排洩指以船舶運送物質至海洋傾倒或處置之行為，並包括海上焚化在內之所有海上作業行為","海域工程指經目的事業主管機關核准之海上風力發電工程；海洋設施指港口管理機關所設置之碼頭、防波堤及倉儲設施；排洩指自陸上污水下水道系統以放流管排入海域之連續性排放行為，不含意外洩漏","海域工程指須辦理環境影響評估之海岸開發案件；海洋設施指海域環境監測站及其附屬觀測儀器；排洩指船舶將壓艙水、洗艙水於航行中排出船外之行為，其餘物質之排出不屬排洩"],"a",
 "第4條第2、5、6款：海域工程指在第2條第1項所定範圍內從事之探勘、開採、輸送、興建、敷設、修繕、抽砂、浚渫、打撈、掩埋、填土、養灘、發電或其他工程；海洋設施指海域工程所設置之人工結構物；排洩指排放、溢出、洩漏廢（污）水、油、廢棄物、有害物質或其他經中央主管機關公告之物質。第20條、第21條即以海洋設施之利用行為為管制對象。",
 "How are marine works, marine facilities and discharge defined?",
 ["Marine works: exploration, extraction, transport, construction, laying, repair, sand mining, dredging, salvage, burial, filling, beach nourishment, power generation and other works in the covered waters; marine facilities: artificial structures built for such works; discharge: releasing, spilling or leaking wastewater, oil, waste or hazardous substances","Marine works: only land reclamation and harbor construction works within the territorial sea, excluding exploration, sand mining, dredging, salvage and beach nourishment; marine facilities: all floating craft and vessels other than ships and aircraft; discharge: carrying substances to sea by vessel for dumping or disposal, including incineration at sea","Marine works: offshore wind power projects approved by the competent industry authority; marine facilities: wharves, breakwaters and warehouses built by port authorities; discharge: continuous release from land sewer outfalls into the sea, excluding accidental leaks","Marine works: coastal development projects requiring environmental impact assessment; marine facilities: marine monitoring stations and their instruments; discharge: releasing ballast and tank-washing water while under way, other substances excluded"],
 "Article 4, subparagraphs 2, 5 and 6."),

(OP,"第4條",2,"海污法-用詞定義",
 "本法所稱海難、海洋棄置、海洋廢棄物及船舶所有人，其定義為何？",
 ["海難指船舶故障、沉沒、擱淺、碰撞、失火、爆炸或其他非常事故；海洋棄置指利用船舶、航空器或海洋設施運送物質至海洋傾倒、排洩或處置；海洋廢棄物指遭人為丟置或遺棄進入海洋之持久性固體；船舶所有人包括所有權人、承租人、經理人及營運人","海難指船舶因天災而發生之沉沒或擱淺，不含碰撞與失火；海洋棄置指自陸上以管線將廢棄物排入海洋之行為；海洋廢棄物指海上漂流之一切有機物與無機物；船舶所有人僅指登記名義之船舶所有權人，不含承租人、經理人與營運人","海難指造成人員傷亡之海上交通事故；海洋棄置指將船舶或人工構造物遺棄於海洋之行為；海洋廢棄物指經中央主管機關公告之甲類物質；船舶所有人指船舶保險契約之要保人及被保險人，並包括其保險代理人","海難指船舶於港區內發生之擱淺與碰撞事故；海洋棄置指利用海洋設施焚化油或其他物質之行為；海洋廢棄物指港區底泥及浚渫土方；船舶所有人指船長及其僱用之船員，並包括船舶代理業與貨物託運人"],"a",
 "第4條第8至13款：海難指船舶發生故障、沉沒、擱淺、碰撞、失火、爆炸或其他有關船舶、貨載、船員或旅客之非常事故；海洋棄置指利用船舶、航空器、海洋設施或其他設施運送物質至海洋傾倒、排洩或處置；海洋廢棄物指遭人為丟置或遺棄進入海洋之任何人造或經加工之持久性固體；海上焚化指利用船舶或海洋設施焚化油或其他物質；船舶所有人指船舶所有權人、承租人、經理人及營運人。第33條即課予船長及船舶所有人海難時之通報與應變義務。",
 "How are maritime peril, ocean dumping, marine debris and shipowner defined?",
 ["Maritime peril: breakdown, sinking, grounding, collision, fire, explosion or other extraordinary incidents; ocean dumping: carrying substances to sea by ship, aircraft or marine facility for dumping or disposal; marine debris: persistent man-made solids discarded into the sea; shipowner: owner, charterer, manager and operator","Maritime peril: sinking or grounding caused by natural disasters only, excluding collision, fire and explosion; ocean dumping: piping waste from land directly into the sea; marine debris: all organic and inorganic matter drifting at sea; shipowner: only the registered owner of the ship, excluding charterers, managers and operators","Maritime peril: sea traffic accidents causing casualties; ocean dumping: abandoning a vessel or artificial structure at sea; marine debris: Class A substances announced by the central authority; shipowner: the policyholder and insured of the hull insurance and their agents","Maritime peril: grounding and collision occurring inside port areas; ocean dumping: incinerating oil or other substances using marine facilities; marine debris: port sediment and dredged spoil; shipowner: the master and crew, plus shipping agents and cargo shippers"],
 "Article 4, subparagraphs 8-13."),

(OP,"第5條",1,"海污法-執行機關",
 "依本法執行取締、蒐證、移送等事項，應由何機關辦理？主管機關及執行機關可否要求他機關協助？",
 ["由執行機關辦理；主管機關及執行機關就該等事項，得要求協助執行機關協助辦理","由主管機關自行辦理；主管機關就該等事項，不得要求其他任何機關協助辦理","由目的事業主管機關辦理；執行機關僅得於接獲通報後提供船舶及人力支援","由港口管理機關辦理；主管機關就該等事項，應報請行政院指定機關協助辦理"],"a",
 "第5條：依本法執行取締、蒐證、移送等事項，由執行機關（海岸巡防機關）辦理；主管機關及執行機關就前項所定事項，得要求協助執行機關協助辦理。第3條第3項定明協助執行機關指軍事、海關或其他相關機關。",
 "Which agency carries out interception, evidence-gathering and case referral, and may it seek help?",
 ["The enforcement authority; the competent and enforcement authorities may request assisting authorities to help with those matters","The competent authority itself; it may not request any other agency to assist with those matters in any circumstance","The relevant industry authority; the enforcement authority may only supply vessels and manpower after being notified","The port authority; the competent authority must ask the Executive Yuan to designate agencies to assist with those matters"],
 "Article 5."),

(OP,"第6條",2,"海污法-檢查權",
 "主管機關、執行機關或協助執行機關進行海洋污染檢查、鑑定時之權限與受檢者義務為何？",
 ["得派員攜帶證明文件進入港口、其他場所或登臨船舶、海洋設施檢查或鑑定，並命令提供有關資料；受檢者不得規避、妨礙或拒絕","得派員逕行進入港口或登臨船舶檢查，無須攜帶任何證明文件；受檢者僅於涉及軍事機密時始得拒絕提供有關資料","應先取得法院核發之搜索票，始得登臨船舶或海洋設施檢查；受檢者於文件送達七日後始負有提供資料之義務","僅得於船舶停靠港口期間進行文件審查，不得登臨船舶；受檢者得以營業秘密為由拒絕提供全部有關資料"],"a",
 "第6條第1項：主管機關、執行機關或協助執行機關，得派員攜帶證明文件，進入港口、其他場所或登臨船舶、海洋設施，檢查或鑑定海洋污染事項，並命令提供有關資料；受檢者不得規避、妨礙或拒絕。第58條對規避、妨礙或拒絕者處新臺幣三十萬元以上一百五十萬元以下罰鍰，並得按次處罰及強制執行檢查。",
 "What powers do the authorities have when inspecting marine pollution, and what must the inspected party do?",
 ["They may send personnel with credentials into ports and other premises or board ships and marine facilities to inspect or appraise and order production of data; the inspected party may not evade, obstruct or refuse","They may enter ports or board ships directly without carrying any credentials; the inspected party may refuse to produce data only where military secrets are involved","They must first obtain a court warrant issued by a judge before entering premises or boarding ships and marine facilities; the inspected party owes a duty to produce data only seven days after service of the written documents","They may only review documents while a ship is berthed and may not board it; the inspected party may refuse to produce all data by invoking trade secrets"],
 "Article 6, paragraph 1; Article 58."),

(OP,"第6條",2,"海污法-檢查程序",
 "依第六條命提供資料涉及軍事機密時應如何辦理？檢查涉及軍事事務之程序辦法由誰訂定？",
 ["涉及軍事機密者，應會同當地軍事機關為之；涉及軍事事務之程序、方法及其他相關事項之辦法，由中央主管機關會同國防部定之","涉及軍事機密者，應報請行政院同意後為之；涉及軍事事務之程序、方法及其他相關事項之辦法，由國防部會同外交部定之","涉及軍事機密者，得逕行免除受檢者提供義務；涉及軍事事務之程序、方法及其他相關事項之辦法，由執行機關會商港口管理機關定之","涉及軍事機密者，應委由協助執行機關單獨為之；涉及軍事事務之程序、方法及其他相關事項之辦法，由中央主管機關逕行公告實施"],"a",
 "第6條第2項：依前項規定命提供資料時，其涉及軍事機密者，應會同當地軍事機關為之。第3項：第1項檢查或鑑定涉及軍事事務之程序、方法及其他相關事項之辦法，由中央主管機關會同國防部定之。第3條第3項亦將軍事機關列為協助執行機關之一。",
 "How are military secrets handled during inspections, and who sets the procedures for military-related inspections?",
 ["Where military secrets are involved, it must be done jointly with the local military authority; regulations on procedures and methods are set by the central authority together with the Ministry of National Defense","Where military secrets are involved, prior Executive Yuan approval must be obtained before any request; regulations on procedures and methods are set by the Ministry of National Defense together with the foreign ministry","Where military secrets are involved, the duty to produce data is simply waived; regulations on procedures and methods are set by the enforcement authority with port authorities","Where military secrets are involved, the task is delegated solely to assisting authorities; regulations on procedures and methods are announced by the central authority alone"],
 "Article 6, paragraphs 2 and 3."),

(OP,"第7條",1,"海污法-委託與白皮書",
 "主管機關及執行機關得如何運用外部資源辦理海洋污染防治事項？中央主管機關對白皮書負有何義務？",
 ["得指定或委託相關機關（構）、法人或團體辦理海洋污染防治、監測、處理、環境保護及研究訓練事項；中央主管機關應發布國家海洋污染防治白皮書並定期檢討修正","僅得委託公立研究機構辦理海洋污染監測事項，不得委託法人或民間團體；中央主管機關應每十年發布一次國家海洋污染防治白皮書，發布後不再檢討修正","得指定或委託相關機關（構）、法人或團體辦理污染處理與研究訓練事項；國家海洋污染防治白皮書應由行政院發布，中央主管機關僅負責提供基礎資料","得將取締、蒐證及裁處等公權力事項一併委託民間團體辦理；中央主管機關應發布國家海洋污染防治白皮書，並於發布前送立法院審議通過"],"a",
 "第7條第1項：主管機關及執行機關得指定或委託相關機關（構）、法人或團體，辦理海洋污染防治、海洋污染監測、海洋污染處理、海洋環境保護及其研究訓練之有關事項。第2項：中央主管機關應發布國家海洋污染防治白皮書，並依國內外情勢發展定期檢討修正之。",
 "How may the authorities use outside bodies, and what duty applies to the national white paper?",
 ["They may designate or commission agencies, juridical persons or groups to handle prevention, monitoring, treatment, protection and related research and training; the central authority must issue and periodically review a national white paper","They may commission only public research institutes to handle monitoring work, and not juridical persons or private groups; the central authority issues a national white paper once every ten years and need not review or revise it afterwards","They may designate or commission bodies for treatment and research and training; the white paper is issued by the Executive Yuan, with the central authority merely supplying background data","They may also delegate interception, evidence-gathering and penalty powers to private groups; the white paper must be sent to the Legislative Yuan for approval before issue"],
 "Article 7."),

# ---------- 第二章 基本措施 ----------
(OP,"第8條",2,"海污法-環境標準",
 "中央主管機關就海域環境分類、品質標準及海洋管制區之訂定權限為何？",
 ["應視海域狀況訂定海域環境分類及海洋環境品質標準；並得依環境分類、品質標準及海域環境特質劃定海洋管制區，訂定海洋環境管制標準，據以訂定分區執行計畫及污染管制措施後公告實施","應視海域狀況訂定海域環境分類及海洋環境品質標準；海洋管制區之劃定與管制標準之訂定，專屬各直轄市、縣（市）主管機關權限，中央僅得於地方逾期未辦時代行公告","應由各目的事業主管機關分別訂定其主管海域之環境分類與品質標準；中央主管機關僅負責彙整並報請行政院核定後，交由港口管理機關訂定分區執行計畫及管制措施","應依國際海事組織所定標準逕行適用，不另訂國內標準；海洋管制區之劃定應先徵得區內漁業權人及海域工程業者全體書面同意後，始得公告實施並執行管制措施"],"a",
 "第8條第1項：中央主管機關應視海域狀況，訂定海域環境分類及海洋環境品質標準。第2項：為維護海洋環境或應目的事業主管機關對特殊海域環境之需求，得依海域環境分類、海洋環境品質標準及海域環境特質，劃定海洋管制區，訂定海洋環境管制標準，並據以訂定分區執行計畫及污染管制措施後公告實施。第53條對違反公告污染管制措施者處二十萬元以上二千萬元以下罰鍰。",
 "What powers does the central authority have over sea area classification, quality standards and controlled zones?",
 ["It must set sea area classifications and marine environment quality standards, and may designate controlled marine zones, set control standards, and announce zoned implementation plans and pollution control measures accordingly","It must set classifications and quality standards, but designating controlled zones and setting control standards belong exclusively to local authorities, with the center acting only if they default","Each relevant industry authority sets sea area classifications and quality standards for its own waters; the central authority merely compiles them for Executive Yuan approval and lets port authorities draw up the zoned implementation plans","IMO standards apply directly with no domestic standards; controlled zones may be designated only after unanimous written consent of fishing right holders and marine works operators"],
 "Article 8; Article 53."),

(OP,"第8條",2,"海污法-污染管制措施",
 "依第八條第二項公告之污染管制措施，包括哪些內容？",
 ["包括污染排放、使用毒品或藥品捕殺水生物，及其他經中央主管機關公告禁止造成海洋污染之行為","僅包括船舶排放油及廢（污）水之行為，不及於捕殺水生物或其他造成海洋污染之行為","僅包括海洋棄置與海上焚化二類行為，其餘污染行為應依廢棄物清理法規定另行管制","僅包括陸上污染源之放流水排放行為，海域工程及海洋設施之排放不在管制措施範圍內"],"a",
 "第8條第3項：前項污染管制措施，包括污染排放、使用毒品、藥品捕殺水生物及其他中央主管機關公告禁止造成海洋污染之行為。違反公告之污染管制措施者，依第53條處新臺幣二十萬元以上二千萬元以下罰鍰，並得限期令其改善，屆期未改善者按次處罰。",
 "What do the announced pollution control measures under Article 8(2) cover?",
 ["Pollution discharges, the use of poisons or drugs to kill aquatic life, and other acts announced by the central authority as prohibited causes of marine pollution","Only discharges of oil and wastewater from ships and marine facilities, excluding the use of poisons to kill aquatic life or other acts causing marine pollution","Only ocean dumping and marine incineration, with all other polluting acts controlled separately under the Waste Disposal Act","Only effluent discharges from land-based sources, with marine works and marine facility discharges excluded from the measures"],
 "Article 8, paragraph 3; Article 53."),

(OP,"第9條",2,"海污法-海域監測",
 "主管機關就所轄海域之環境監測負有何義務？對監測站或設施有何禁止規定？",
 ["應依海域環境分類設置海域環境監測站或設施，定期公布監測結果並採取適當防治措施，必要時各目的事業主管機關得公告限制海域之使用；任何人不得干擾或毀損該監測站或設施","應依海域環境分類設置海域環境監測站或設施，每五年公布監測結果一次即可，且不得限制海域之使用；監測站或設施之維護管理由設置廠商自行負責，他人得自由使用","應委由各港口管理機關設置監測設施並公布結果，主管機關不自行設站；必要時得由港口管理機關公告限制海域使用，干擾或毀損監測設施者僅生民事賠償責任","應由中央主管機關統一設置全國監測站，地方主管機關不得設站；監測結果屬機密不得對外公布，但得提供學術機構研究使用，毀損監測設施者依刑法處罰"],"a",
 "第9條第1項：主管機關應依海域環境分類，就其所轄海域設置海域環境監測站或設施，定期公布監測結果，並採取適當防治措施；必要時，各目的事業主管機關並得公告限制海域之使用。第2項：對主管機關設置之監測站或設施，不得干擾或毀損。第59條對違反限制海域使用公告或干擾、毀損監測設施者，處二十萬元以上一百萬元以下罰鍰。",
 "What monitoring duties do the authorities have, and what is prohibited regarding monitoring stations?",
 ["They must set up monitoring stations or facilities by sea area class, publish results periodically and take control measures; where necessary industry authorities may restrict use of sea areas; no one may disturb or damage those stations","They must set up monitoring stations or facilities by sea area class but need publish results only every five years and may not restrict use of sea areas; maintenance rests with the installing contractor and anyone may freely use them","Port authorities are to install monitoring facilities and publish results instead of the competent authority; damaging a facility gives rise only to civil liability","Only the central authority may install stations nationwide; results are confidential and may not be published, though they may be given to academic institutions for research"],
 "Article 9, paragraphs 1 and 2; Article 59."),

(OP,"第9條",2,"海污法-港區污染",
 "各類港口管理機關及事業機構就港區污染負有何義務？相關檢測辦法由誰訂定？",
 ["應評估所轄港區使用狀況，辦理港區水質及底泥檢測，並採取措施防止、排除或減輕港區污染；相關檢測及監測辦法由中央主管機關會商各目的事業主管機關定之","應評估所轄港區使用狀況並辦理水質檢測，但底泥檢測應由中央主管機關自行辦理；相關檢測及監測辦法由各港口管理機關擬訂後報請行政院核定實施","應委託環境檢驗測定機構每十年辦理港區水質及底泥檢測一次，無須採取防治措施；相關檢測及監測辦法由各類港口目的事業主管機關逕行公告後實施","應於發生污染事件後始辦理港區水質及底泥檢測，平時無檢測義務；相關檢測及監測辦法由地方主管機關會商港口事業機構訂定並報中央備查"],"a",
 "第9條第3項：各類港口管理機關及事業機構應評估所轄港區使用狀況，辦理港區水質及底泥檢測，並依本法及其他相關規定採取措施，以防止、排除或減輕港區之污染；必要時地方主管機關及相關機關應配合共同採取防治措施。第4項：各類港口目的事業主管機關應輔導所轄港區之污染改善。第5項：監測項目、設站基準、採樣分析方法及港區水質與底泥檢測辦法，由中央主管機關會商各目的事業主管機關定之。",
 "What duties do port authorities and enterprises have over port pollution, and who sets the testing rules?",
 ["They must assess port use, conduct water quality and sediment testing, and take measures to prevent, remove or mitigate port pollution; the testing and monitoring regulations are set by the central authority with the relevant industry authorities","They must assess port area use and conduct water quality testing, but sediment testing is carried out by the central authority itself; the testing and monitoring regulations are drafted by port authorities and submitted for Executive Yuan approval","They must commission testing agencies to test water and sediment once every ten years and need take no control measures; the regulations are announced by port industry authorities alone","They need test water and sediment only after a pollution incident occurs; the regulations are set by local authorities with port enterprises and filed with the center for record"],
 "Article 9, paragraphs 3-5."),

(OP,"第10條",2,"海污法-應變組織",
 "為處理重大及一般海洋污染事件，本法設有何種組織安排？",
 ["為處理重大海洋污染事件，行政院得設重大海洋污染事件處理專案小組；為處理一般海洋污染事件，中央主管機關得設海洋污染事件處理工作小組","為處理重大海洋污染事件，中央主管機關得設重大海洋污染事件處理專案小組；為處理一般海洋污染事件，地方主管機關得設海洋污染事件處理工作小組","為處理重大海洋污染事件，國家安全會議得設重大海洋污染事件處理專案小組；為處理一般海洋污染事件，執行機關得設海洋污染事件處理工作小組","為處理重大海洋污染事件，行政院得設重大海洋污染事件處理專案小組；為處理一般海洋污染事件，各港口管理機關應設海洋污染事件處理工作小組"],"a",
 "第10條第1項：為處理重大海洋污染事件，行政院得設重大海洋污染事件處理專案小組；為處理一般海洋污染事件，中央主管機關得設海洋污染事件處理工作小組。第2項並要求中央主管機關擬訂重大海洋污染緊急應變計畫報請行政院核定。",
 "What organizational arrangements exist for handling major and ordinary marine pollution incidents?",
 ["The Executive Yuan may establish a major marine pollution incident task force; the central competent authority may establish a working group for ordinary incidents","The central competent authority may establish the major incident task force; local competent authorities may establish working groups for ordinary incidents","The National Security Council may establish the major incident task force; the enforcement authority may establish working groups for ordinary incidents","The Executive Yuan may establish the major incident task force; every port authority must establish a working group for ordinary incidents"],
 "Article 10, paragraph 1."),

(OP,"第10條",2,"海污法-緊急應變計畫",
 "重大海洋污染緊急應變計畫與地方海洋污染緊急應變計畫之擬訂程序及內容為何？",
 ["中央主管機關應擬訂重大海洋污染緊急應變計畫報請行政院核定；地方主管機關應訂定海洋污染緊急應變計畫報請中央主管機關備查；計畫應包含分工、通報系統、監測系統、訓練、設施及處理措施","中央主管機關應擬訂重大海洋污染緊急應變計畫報請立法院同意；地方主管機關應訂定海洋污染緊急應變計畫報請行政院核定；計畫應包含分工、通報系統、財源及賠償標準等事項","行政院應擬訂重大海洋污染緊急應變計畫送中央主管機關備查；地方主管機關訂定之應變計畫無須報請備查；計畫僅須載明通報系統與處理措施，訓練及設施得免予規劃","中央主管機關應擬訂重大海洋污染緊急應變計畫並逕行公告；地方主管機關得視需要決定是否訂定應變計畫；計畫應包含分工、監測系統、保險額度及求償程序等相關事項"],"a",
 "第10條第2項：為處理重大海洋污染緊急事件，中央主管機關應擬訂重大海洋污染緊急應變計畫，報請行政院核定之；為處理管轄範圍內之海洋污染緊急事件，直轄市、縣（市）主管機關應訂定海洋污染緊急應變計畫，報請中央主管機關備查。第3項：緊急應變計畫應包含分工、通報系統、監測系統、訓練、設施、處理措施及其他相關事項。",
 "How are the national and local marine pollution emergency response plans adopted, and what must they contain?",
 ["The central authority drafts the major incident emergency plan for Executive Yuan approval; local authorities adopt plans filed with the central authority for record; plans must cover division of work, notification, monitoring, training, facilities and response measures","The central authority drafts the major incident emergency plan for Legislative Yuan consent; local authorities adopt plans submitted for Executive Yuan approval; plans must cover division of work, notification, funding sources, insurance and compensation criteria","The Executive Yuan drafts the major incident plan and files it with the central authority; local plans need not be filed at all; plans need only state notification systems and response measures","The central authority drafts and announces the plan directly; local authorities may decide whether to adopt a plan; plans must cover division of work, monitoring, insurance limits and claim procedures"],
 "Article 10, paragraphs 2 and 3."),

(OP,"第11條",2,"海污法-防治費",
 "中央主管機關應向哪些對象徵收海洋污染防治費？",
 ["經中央主管機關許可從事海洋棄置者；在我國潮間帶、內水、領海範圍內接收、運輸原油或其他公告指定物質之進口業者；從事海域工程或利用海洋設施達公告規模者","經中央主管機關許可從事海洋棄置者；在我國專屬經濟海域內作業之外國籍漁船經營者；從事海域工程或利用海洋設施而未達公告規模之小型業者及其承攬廠商","經地方主管機關登記之港區裝卸業者；在我國領海內航行之一切客貨船舶所有人；從事海岸工程或利用海岸防護設施達中央主管機關公告規模之興辦事業者","經中央主管機關許可排放廢（污）水入海之陸上工廠；在我國海域從事潛水及水上遊憩活動之業者；從事海洋科學研究或投放人工魚礁之學術機構及漁會團體"],"a",
 "第11條第1項：中央主管機關應向下列對象徵收海洋污染防治費：一、經中央主管機關許可從事海洋棄置者。二、在我國潮間帶、內水、領海範圍內接收、運輸原油或其他經中央主管機關公告指定物質之進口業者。三、從事海域工程或利用海洋設施達中央主管機關公告之規模者。第12條並以海洋污染防治費為海洋污染防治基金之來源之一。",
 "From whom must the central authority collect the marine pollution control fee?",
 ["Permitted ocean dumpers; importers receiving or transporting crude oil or other designated substances within the intertidal zone, internal waters or territorial sea; and those doing marine works or using marine facilities at or above the announced scale","Permitted ocean dumpers; operators of foreign-flagged fishing vessels working within the ROC exclusive economic zone; and small operators and their subcontractors doing marine works or using marine facilities below the announced scale of operations","Port stevedoring firms registered with local authorities; owners of all passenger and cargo ships sailing in the territorial sea; and undertakings doing coastal works at the announced scale","Land-based factories permitted to discharge wastewater to sea; diving and water recreation operators in ROC waters; and academic bodies and fishermen's associations placing artificial reefs"],
 "Article 11, paragraph 1; Article 12."),

(OP,"第11條",1,"海污法-防治費辦法",
 "海洋污染防治費之徵收時間、費率、對象及繳納期限等事項，應由誰訂定？",
 ["由中央主管機關會商有關機關訂定辦法，內容包括徵收時間、項目、費率、對象、方式、繳納期限及減免等事項","由中央主管機關報請立法院審議通過後實施，內容包括徵收時間、項目、費率、對象及減免等應遵行事項","由各直轄市、縣（市）主管機關分別訂定自治條例，內容包括徵收時間、費率、對象、方式及繳納期限等事項","由行政院會商財政部訂定收費標準，內容包括徵收時間、項目、費率、對象、方式及減免等應遵行事項"],"a",
 "第11條第2項：海洋污染防治費之徵收時間、徵收項目、徵收費率、徵收對象、徵收方式、繳納期限、減免及其他應遵行事項之辦法，由中央主管機關會商有關機關定之。第61條並定明未依該辦法所定繳納期限繳費者，應按日加計利息，逾期九十日仍未繳納者處六千元以上三十萬元以下罰鍰。",
 "Who prescribes the timing, rates, payers and payment deadlines of the marine pollution control fee?",
 ["The central competent authority, in consultation with relevant agencies, by regulations covering timing, items, rates, payers, methods, deadlines and reductions","The central competent authority, after approval by the Legislative Yuan, by rules covering timing, items, rates, payers and reductions to be observed","Each municipal and county competent authority, by its own self-government ordinance covering timing, rates, payers, methods and payment deadlines","The Executive Yuan together with the Ministry of Finance, by a fee schedule covering timing, items, rates, payers, methods and reductions"],
 "Article 11, paragraph 2; Article 61."),

(OP,"第12條",1,"海污法-防治基金",
 "海洋污染防治基金之來源包括哪些？",
 ["海洋污染防治費；各有關機關依本法求償採取應變措施、清除及處理所生費用歸墊之收入；基金孳息收入；其他有關收入","海洋污染防治費；依本法所裁處之全部罰鍰及罰金收入；基金孳息收入；中央政府依預算程序循年度編列撥充之公務預算","海洋污染防治費；船舶所有人依法投保責任保險之保費分成收入；基金孳息收入；港口管理機關收取之污染物處理費用","海洋污染防治費；海域工程業者繳納之開發許可規費收入；基金孳息收入；國際組織及外國政府提供之補助與捐贈款項"],"a",
 "第12條：中央主管機關得設置海洋污染防治基金，其基金來源為海洋污染防治費、各有關機關依本法求償採取應變措施清除及處理所生費用歸墊之收入、基金孳息收入及其他有關收入。第13條定明基金之用途，第15條第4項並規定緊急污染事件所需費用得由基金代為支應後向污染行為人求償。",
 "What are the sources of the marine pollution control fund?",
 ["The marine pollution control fee; reimbursements recovered by agencies for response, removal and treatment costs under this Act; interest on the fund; and other related income","The control fee; all administrative fines and criminal fines imposed under this Act; interest on the fund; and annual government budget appropriations made through the budget process","The control fee; a share of liability insurance premiums paid by shipowners; interest on the fund; and pollutant treatment fees collected by port authorities","The control fee; development permit charges paid by marine works operators; interest on the fund; and grants and donations from international organizations and foreign governments"],
 "Article 12; Articles 13 and 15."),

(OP,"第13條",2,"海污法-基金用途",
 "海洋污染防治基金之用途包括下列何者？",
 ["發生污染或有污染之虞時各機關採取應變措施、清除及處理所需費用；污染發生時執行海洋環境品質監測及損害調查費用；購置防治及應變設備資材費用","發生污染或有污染之虞時各機關採取應變措施所需費用；污染受害漁民之營業損失補償金；購置防治及應變設備資材費用及港口設施之興建改良工程經費","發生污染時執行海洋環境品質監測及損害調查費用；污染行為人所受行政罰鍰之代墊；主管機關人員之退休撫卹給與及各級機關辦公廳舍之修繕維護費用","購置海洋污染防治及應變設備資材之費用；船舶所有人責任保險保費之補助；海域工程業者因停工所受營業損失之補償及其法律訴訟費用之全額負擔"],"a",
 "第13條：海洋污染防治基金應專供全國海洋污染防治與應變措施、清除、處理及其他有關海洋污染防治工作之用，用途包括各有關機關採取應變措施清除及處理所需費用、執行海洋環境品質監測及損害調查費用、購置防治及應變設備資材費用等。第35條並列明各機關依本法求償所生費用之項目。",
 "Which of the following are permitted uses of the marine pollution control fund?",
 ["Costs of response, removal and treatment by agencies when pollution occurs or is imminent; costs of environmental quality monitoring and damage investigation when pollution occurs; and purchase of control and response equipment and materials","Costs of agency response measures when pollution occurs or is imminent; compensation for the business losses of affected fishermen and aquaculture farms; and purchase of response equipment plus construction and improvement of port facilities","Costs of quality monitoring and damage investigation when pollution occurs; advances covering administrative fines owed by polluters; and pension payments for staff and repairs of government office buildings","Purchase of marine pollution control and response equipment and materials; subsidies for shipowners' liability insurance premiums; and full compensation of marine works operators' losses from work stoppage"],
 "Article 13; Article 35."),

(OP,"第13條",2,"海污法-基金用途",
 "除應變清除費用外，海洋污染防治基金尚得用於下列哪些項目？",
 ["各有關機關依本法求償及涉訟之費用；執行海洋污染防治及收費工作所需人員之聘僱；補助與獎勵海洋污染防治研究及技術開發；其他與海洋污染防治工作有關之支出","各有關機關依本法求償及涉訟之費用；污染行為人依法應繳納罰鍰之減免補貼；補助民間團體從事海洋觀光遊憩活動之推廣；其他與海運產業發展有關之支出","執行海洋污染防治及收費工作所需人員之聘僱；地方政府一般性公共建設之配合款；補助漁業團體購置漁船與漁具之貸款利息；其他與漁業資源培育有關之支出","補助與獎勵海洋污染防治研究及技術開發；受污染土地之徵收補償與地價補貼；補助船舶所有人汰換老舊船舶之購船價款；其他與造船工業升級有關之支出"],"a",
 "第13條第4至7款：基金用途包括各有關機關依本法求償及涉訟之費用、執行海洋污染防治及收費工作所需人員之聘僱、補助與獎勵海洋污染防治研究及技術開發，以及其他與海洋污染防治工作有關之支出。基金來源見第12條，求償費用項目見第35條，第39條並定明該等求償權優於抵押權、留置權及一般債權。",
 "Besides response and cleanup costs, what else may the fund be used for?",
 ["Agencies' costs of claims and litigation under this Act; hiring personnel for control and fee collection work; subsidies and awards for control research and technology development; and other expenses related to marine pollution control","Agencies' costs of claims and litigation; subsidies offsetting fines payable by polluters; grants to private groups promoting marine tourism and recreation; and other expenses related to shipping industry development","Hiring personnel for pollution control and fee collection work; matching funds for general local public works; interest subsidies on loans for fishing vessels and gear; and other expenses related to fishery resource cultivation","Subsidies and awards for control research and technology development; expropriation compensation and land price subsidies for polluted land; subsidies for replacing old ships; and other shipbuilding upgrade expenses"],
 "Article 13, subparagraphs 4-7; Articles 12, 35 and 39."),

(OP,"第14條",1,"海污法-陸域防止",
 "與本法適用水域相連之陸域及海洋以外地面水體，其轄管機關負有何種義務？",
 ["應採取措施，以防止、排除或減輕廢棄物污染海洋","應每年編列預算辦理水質檢測，但無防止污染之義務","應報請中央主管機關核定其污染管制計畫後始得管理","應委託海岸巡防機關代為執行陸域廢棄物清理事項"],"a",
 "第14條：與第2條第1項所定水域相連之陸域及海洋以外地面水體，其轄管機關應採取措施，以防止、排除或減輕廢棄物污染海洋。第18條另規定非經中央主管機關許可，不得排放廢（污）水於與海域相鄰接之自然保留區、國家公園等特定區域。",
 "What duty falls on authorities governing land and non-marine surface waters connected to the covered waters?",
 ["They must take measures to prevent, remove or mitigate pollution of the sea by waste","They must budget annually for water testing but bear no duty to prevent pollution","They must obtain central approval of a control plan before exercising management","They must commission the coast guard to carry out land-based waste cleanup for them"],
 "Article 14; Article 18."),

(OP,"第15條",2,"海污法-事前許可",
 "從事油輸送、海域工程、海洋棄置或其他可能造成海洋污染行為達公告規模者，事前應完成何種程序？",
 ["應先提出足以預防及處理海洋污染之緊急應變計畫及賠償污染損害之財務保證書或責任保險單，經中央主管機關許可後始得為之","應先提出海洋污染防治計畫及環境影響說明書，經目的事業主管機關備查後即得為之，無須取得中央主管機關之許可","應先繳納海洋污染防治費並投保責任保險，於向地方主管機關報備後即得為之，緊急應變計畫得於開工後補行提出","應先取得海岸巡防機關核發之作業證明並完成船舶檢查，經行政院核定後始得為之，財務保證書得以切結書代替"],"a",
 "第15條第1項：從事油輸送、海域工程、海洋棄置或其他可能造成海洋污染之行為達中央主管機關公告之規模者，應先提出足以預防及處理海洋污染之緊急應變計畫及賠償污染損害之財務保證書或責任保險單，經中央主管機關許可後始得為之。第2、3項定明應變計畫內容由中央主管機關定之，保證額度或責任限額由中央主管機關會商金融監督管理委員會定之。第47條對未經許可者處三十萬元以上一億元以下罰鍰。",
 "What must be completed beforehand by those engaging in oil transport, marine works or ocean dumping at the announced scale?",
 ["They must first submit an emergency response plan adequate to prevent and handle marine pollution plus a financial guarantee or liability insurance policy for damages, and obtain the central authority's permit","They must first submit a marine pollution control plan and an environmental impact statement and file them with the relevant industry authority, without needing any permit from the central authority at all","They must first pay the control fee and take out liability insurance and report to the local authority, with the emergency response plan submitted after work begins","They must first obtain a coast guard operating certificate and complete ship inspection with Executive Yuan approval; an affidavit may replace the financial guarantee"],
 "Article 15, paragraphs 1-3; Article 47."),

(OP,"第15條",2,"海污法-緊急協助",
 "海洋發生緊急污染事件時，主管機關得對業者為何種要求？所需費用如何負擔？",
 ["得要求第十五條第一項之業者或其他海洋相關事業提供污染處理設備、專業技術人員協助處理，所需費用由污染行為人負擔，必要時得由海洋污染防治基金代為支應再行求償","得要求第十五條第一項之業者無償提供污染處理設備及人員協助處理，所需費用一律由該提供協助之業者自行吸收，不得向污染行為人或基金請求任何補償","得要求任何船舶所有人停止航行並提供船舶供主管機關徵用，所需費用由港口管理機關負擔，事後不得向污染行為人求償或由基金支應","得要求目的事業主管機關指定廠商代為處理，所需費用由中央政府年度公務預算全額支應，污染行為人僅於故意或重大過失時始負擔費用"],"a",
 "第15條第4項：主管機關於海洋發生緊急污染事件時，得要求第1項之業者或其他海洋相關事業，提供污染處理設備、專業技術人員協助處理，所需費用由污染行為人負擔；必要時得由海洋污染防治基金代為支應，再向污染行為人求償。第47條第2項對未依規定協助處理緊急污染事件者，處五十萬元以上五千萬元以下罰鍰。",
 "In a marine pollution emergency, what may the authority require of operators, and who bears the costs?",
 ["It may require Article 15(1) operators or other marine businesses to supply treatment equipment and technical personnel; costs are borne by the polluter, and where necessary the fund may advance them and then seek recovery","It may require Article 15(1) operators to supply treatment equipment and technical personnel free of charge, with those operators absorbing all of the costs themselves and having no claim against the polluter or the control fund","It may order any shipowner to stop sailing and hand over the vessel for requisition, with costs borne by the port authority and no recovery from the polluter or the fund","It may have the industry authority designate contractors, with costs fully met from the central government budget and the polluter liable only for intent or gross negligence"],
 "Article 15, paragraph 4; Article 47, paragraph 2."),

(OP,"第16條",2,"海污法-清除責任",
 "海洋污染之清除責任歸屬為何？主管機關得否逕行處理？費用由誰負擔？",
 ["海洋污染應由污染行為人負責清除；必要時目的事業主管機關或主管機關得逕行採取應變措施、清除及處理，其所生費用由污染行為人負擔","海洋污染應由主管機關負責清除；必要時得命污染行為人協助處理，其所生費用由海洋污染防治基金全額支應，不得向污染行為人求償","海洋污染應由發現污染之港口管理機關負責清除；污染行為人僅負通報義務，其應變措施、清除及處理費用由中央政府編列預算支應","海洋污染應由污染行為人與土地所有人連帶負責清除；主管機關不得逕行採取應變措施，須待法院判決確定後始得代為清除並求償"],"a",
 "第16條第1項：海洋污染應由污染行為人負責清除之。必要時，目的事業主管機關或主管機關得逕行採取應變措施、清除及處理；其因應變措施、清除及處理所生費用，由污染行為人負擔。第54條對未依第16條第1項前段清除污染者，處十萬元以上一千萬元以下罰鍰，並得限期令其清除，屆期未清除者按次處罰。",
 "Who must clean up marine pollution, may the authority act directly, and who pays?",
 ["The polluter must clean up; where necessary the industry or competent authority may itself take response, removal and treatment action, with the resulting costs borne by the polluter","The competent authority must clean up and may order the polluter to assist; the costs are fully met by the control fund with no recovery from the polluter","The port authority that discovers the pollution must clean up; the polluter owes only a duty to notify, and response costs are met from the central government budget","The polluter and the landowner are jointly liable to clean up; the authority may not act directly and must await a final court judgment before cleaning up and claiming costs"],
 "Article 16, paragraph 1; Article 54."),

(OP,"第16條",2,"海污法-免罰事由",
 "造成海洋污染而不予處罰之情形，包括下列何者？",
 ["為緊急避難或確保船舶、航空器、海堤或其他重大工程設施安全；為維護國防安全或因天然災害、戰爭或依法令之行為；為防止減輕污染或特殊研究需要而經中央主管機關同意者","為緊急避難或確保船舶安全；為維護國防安全或因天然災害、戰爭之行為；為降低營運成本或維持生產排程需要，而事先向目的事業主管機關報備並取得同意者","為確保船舶、航空器或海堤安全；為配合國際航運慣例或外國船旗國法令之要求；為進行商業性海洋資源開發而已投保足額責任保險並提供財務保證書者","為維護國防安全或因天然災害、戰爭之行為；為執行海洋棄置作業所必要之排洩行為；為避免船舶滯港損失而經港口管理機關同意於港區內排放廢（污）水者"],"a",
 "第16條第2項：因下列情形之一造成海洋污染者不予處罰：一、為緊急避難或確保船舶、航空器、海堤或其他重大工程設施安全。二、為維護國防安全或因天然災害、戰爭或依法令之行為。三、為防止、排除或減輕污染、保護環境或為特殊研究需要，經中央主管機關同意。第3項並授權中央主管機關訂定海洋污染清除、處理方法及方式之辦法，違反者依第55條第2款處罰。",
 "Which circumstances exempt a person from penalty despite causing marine pollution?",
 ["Emergency avoidance or securing the safety of ships, aircraft, seawalls or other major works; safeguarding national defense or acts due to natural disaster, war or law; and preventing or mitigating pollution or special research with central approval","Emergency avoidance or securing ship safety; safeguarding defense or acts due to disaster or war; and reducing operating costs or maintaining production schedules after reporting to and obtaining industry authority consent","Securing the safety of ships, aircraft, seawalls or major works; complying with international shipping practice or flag state law; and commercial marine resource development where adequate liability insurance and a financial guarantee are in place","Safeguarding defense or acts due to disaster or war; discharges necessary for ocean dumping operations; and discharging wastewater in port with port authority consent to avoid delay losses"],
 "Article 16, paragraphs 2 and 3; Article 55."),

(OP,"第17條",2,"海污法-除役計畫",
 "各目的事業主管機關對經許可投設、敷設或佈放之海洋設施、漁業設施及人工構造物，應如何管理？",
 ["應查核該等設施及人工構造物，並要求訂定、執行除役計畫","應每年公告設施清單，但不得要求業者訂定或執行除役計畫","應委由海岸巡防機關查核，並由業者自行決定是否除役","應於許可期限屆滿時逕行拆除，無須要求業者提出除役計畫"],"a",
 "第17條第1項：各目的事業主管機關應查核經許可於第2條第1項所定範圍內投設、敷設或佈放之各類海洋設施、漁業設施及其他人工構造物，並要求訂定、執行除役計畫。第2項並定明未依除役計畫執行或未經許可投設者，得限期令其改善，屆期未改善者該設施視為海洋廢棄物。",
 "How must industry authorities manage permitted marine facilities, fishery facilities and artificial structures?",
 ["They must inspect those facilities and artificial structures and require decommissioning plans to be drawn up and carried out","They must publish an annual list of such facilities but may not require operators to draw up or carry out decommissioning plans","They must have the coast guard inspect them and leave the decision on decommissioning to the operators themselves","They must demolish them directly when the permit expires, without requiring operators to submit decommissioning plans"],
 "Article 17, paragraphs 1 and 2."),

(OP,"第17條",2,"海污法-視為海洋廢棄物",
 "許可期限屆滿未依除役計畫執行，或未經許可投設人工構造物者，主管機關得如何處理？",
 ["得限期令其改善；屆期未改善者，該設施或人工構造物視為海洋廢棄物，並得代為清除、處理，所生費用由所有人負擔，所有人不明者以公告方式為之","得逕行沒入該設施或人工構造物並拍賣抵充清除費用；所有人不明者，應停止一切清除處理程序，俟查明所有人身分後再行辦理相關事宜","得處以罰鍰但不得代為清除；該設施或人工構造物仍屬所有人財產，主管機關須經法院判決後始得處理，所生費用由海洋污染防治基金負擔","得命港口管理機關代為拆除並保管；所生費用由中央政府編列年度預算支應，所有人不明或無法通知者，即免除其一切清除處理之責任"],"a",
 "第17條第2項：各目的事業主管機關對許可期限屆滿未依除役計畫執行者，或主管機關對未經許可而為前項行為者，得限期令其改善；屆期未改善者，該設施或人工構造物視為海洋廢棄物，並得代為清除、處理，所生費用由所有人負擔。第3項：所有人不明或無法通知者，以公告方式為之。第4條第11款定明海洋廢棄物之定義。",
 "What may the authority do where a decommissioning plan is not carried out or a structure was placed without permit?",
 ["Order improvement within a time limit; if not improved, the facility is deemed marine debris and may be removed on the owner's account, with public notice used where the owner is unknown","Confiscate and auction the facility to offset removal costs; where the owner is unknown, all removal must stop until the owner's identity is established","Impose a fine but not remove it; the facility remains the owner's property and a court judgment is needed first, with costs borne by the control fund","Order the port authority to demolish and take custody of it; costs come from the central government budget, and an unknown or unreachable owner is released from all removal duties"],
 "Article 17, paragraphs 2 and 3; Article 4, subparagraph 11."),

# ---------- 第三章 防止陸上污染源污染 ----------
(OP,"第18條",2,"海污法-禁止排放區域",
 "非經中央主管機關許可，不得排放廢（污）水於與海域相鄰接之哪些區域？",
 ["自然保留區、地質公園；國家公園、國家自然公園；野生動物保護區、野生動物重要棲息環境；水產動植物繁殖保育區；其他經中央主管機關公告需特別保護之區域","自然保留區、地質公園；國家公園、國家自然公園；商港區及工業專用港區；漁港區及遊艇港區；其他經地方主管機關公告需特別加以保護管理之港灣區域","野生動物保護區、野生動物重要棲息環境；水產動植物繁殖保育區；離島建設條例所定之離島海域；重要濕地與海岸保護區；其他經內政部公告之海岸特定區位","國家公園、國家自然公園；自然保留區、地質公園；海洋庇護區之核心區與緩衝區；水下文化資產保護區；其他經行政院公告禁止一切人為活動之海域範圍"],"a",
 "第18條第1項：非經中央主管機關許可，不得排放廢（污）水於與海域相鄰接之自然保留區、地質公園、國家公園、國家自然公園、野生動物保護區、野生動物重要棲息環境、水產動植物繁殖保育區及其他經中央主管機關公告需特別加以保護之區域。第41條對未經許可排放者，處五年以下有期徒刑，得併科新臺幣一億元以下罰金。",
 "Without central approval, wastewater may not be discharged into which areas adjoining the sea?",
 ["Nature reserves and geoparks; national parks and national nature parks; wildlife refuges and major wildlife habitats; aquatic breeding and conservation areas; and other areas announced as needing special protection","Nature reserves and geoparks; national parks and national nature parks; commercial and industrial port zones; fishing and yacht harbor zones; and other harbor areas announced by local authorities","Wildlife refuges and major wildlife habitats; aquatic breeding and conservation areas; offshore island waters under the Offshore Islands Act; important wetlands and coastal protection zones; and other coastal locations announced by the interior ministry","National parks and national nature parks; nature reserves and geoparks; core and buffer zones of marine sanctuaries; underwater cultural heritage zones; and other waters where the Executive Yuan bans all human activity"],
 "Article 18, paragraph 1; Article 41."),

(OP,"第18條",2,"海污法-排放許可辦法",
 "第十八條第一項廢（污）水排放許可辦法應規範哪些事項？由誰訂定？",
 ["應規範許可之申請、條件、審查程序、廢止、排放許可內容變更、設施停用、排放紀錄製作與備查等事項；由中央主管機關會商相關目的事業主管機關定之","應規範許可之申請、條件、審查程序及廢止等事項，但不含排放紀錄之製作與備查；由各直轄市、縣（市）主管機關分別訂定並報中央主管機關核定","應規範許可之申請、審查程序、收費標準及爭訟程序等事項；由中央主管機關會商金融監督管理委員會定之，並應每三年檢討修正一次後公告","應規範排放水質標準、監測頻率及檢測機構資格等事項；由目的事業主管機關擬訂後，報請行政院核定並送立法院備查後始得實施"],"a",
 "第18條第2項：廢（污）水排放許可之申請、條件、審查程序、廢止、排放許可之內容變更、設施停用、排放紀錄製作與備查及其他應遵行事項之許可辦法，由中央主管機關會商相關目的事業主管機關定之。第55條第3、4款分別對未經許可排放及違反該辦法中內容變更、設施停用、排放紀錄規定者處罰。",
 "What must the Article 18 wastewater discharge permit regulations cover, and who issues them?",
 ["Permit application, conditions, review procedure, revocation, changes to permit content, facility suspension, and preparation and filing of discharge records; issued by the central authority with the relevant industry authorities","Permit application, conditions, review procedure and revocation, but not changes to permit content or the preparation and filing of discharge records; issued by each local authority and approved by the central competent authority","Permit application, review procedure, fee schedules and dispute procedures; issued by the central authority together with the Financial Supervisory Commission and reviewed every three years","Effluent quality standards, monitoring frequency and testing agency qualifications; drafted by the industry authority for Executive Yuan approval and filed with the Legislative Yuan"],
 "Article 18, paragraph 2; Article 55."),

(OP,"第19條",2,"海污法-陸上污染行為",
 "從事哪些行為致嚴重污染海洋或有嚴重污染之虞時，應即採取措施並通知主管機關？",
 ["海洋放流、海岸放流、轉運堆置或處理廢棄物、存放營建工地之貨品或營建材料、存放化學品、運輸油或化學品、港埠作業及其他經公告具污染潛勢之行為","海洋放流、海岸放流、船舶洗艙及壓艙水排放、漁船作業與魚貨卸載、海上遊憩活動、海水浴場經營、潛水教學及其他經地方主管機關公告之遊憩行為","轉運堆置或處理廢棄物、存放化學品、運輸油或化學品、海洋棄置作業、海上焚化作業、人工魚礁投設及其他經漁業主管機關公告具污染潛勢之行為","存放營建工地之貨品或營建材料、港埠作業、海域工程施工、海洋設施探採油礦、海底電纜鋪設及其他經目的事業主管機關指定之海域開發利用行為"],"a",
 "第19條第1項：從事海洋放流、海岸放流、轉運堆置或處理廢棄物、存放營建工地之貨品或營建材料、存放化學品、運輸油或化學品、港埠作業及其他經中央主管機關公告具污染潛勢之行為，致嚴重污染海洋或有嚴重污染海洋之虞時，應即採取措施以防止、排除或減輕污染，並即通知主管機關及目的事業主管機關。第50條、第57條分別對未採取措施及未通知者處罰。",
 "Which activities trigger the duty to act immediately and notify when they seriously pollute or threaten to pollute the sea?",
 ["Marine outfall discharge, coastal outfall discharge, transfer, stacking or treatment of waste, storing construction site goods or materials, storing chemicals, transporting oil or chemicals, port operations, and other announced high-risk acts","Marine and coastal outfall discharge, tank washing and ballast water discharge, fishing operations and catch unloading, marine recreation, bathing beach operation, dive instruction and other recreational acts announced by local competent authorities","Transfer, stacking or treatment of waste, storing chemicals, transporting oil or chemicals, ocean dumping, marine incineration, artificial reef placement and other high-risk acts announced by fisheries authorities","Storing construction site goods or materials, port operations, marine works construction, offshore mineral exploration, submarine cable laying and other marine development acts designated by industry authorities"],
 "Article 19, paragraph 1; Articles 50 and 57."),

(OP,"第19條",2,"海污法-應變命令",
 "陸上污染源污染行為人未自行處理時，主管機關得為何種處置？費用如何負擔？",
 ["得命污染行為人採取必要之應變措施，必要時主管機關並得逕行採取應變措施、清除及處理，所生費用由污染行為人負擔","得命污染行為人採取必要之應變措施，但主管機關不得逕行處理，所生費用一律由海洋污染防治基金全額支應","得命目的事業主管機關代為採取必要之應變措施，所生費用由該目的事業主管機關依其年度預算自行負擔","得命港口管理機關採取必要之應變措施並先行墊付，所生費用於事後由中央政府編列公務預算撥還港口管理機關"],"a",
 "第19條第2項：主管機關得命前項污染行為人採取必要之應變措施，必要時，主管機關並得逕行採取應變措施、清除及處理；其因應變措施、清除及處理所生費用，由污染行為人負擔。第22條、第26條、第33條就海域工程、海洋棄置及海難情形設有相同規定，第50條並對未依主管機關命令辦理者處三十萬元以上三千萬元以下罰鍰。",
 "If a land-based polluter fails to act, what may the authority do and who bears the costs?",
 ["It may order the polluter to take necessary response measures, and where necessary take response, removal and treatment action itself, with the costs borne by the polluter","It may order the polluter to take necessary response measures but may not act itself, and the resulting costs are met in full by the marine pollution control fund","It may direct the industry authority to take response measures on its behalf, with that authority bearing the costs out of its own annual budget","It may order the port authority to take response measures and advance the costs, which are later reimbursed from the central government budget"],
 "Article 19, paragraph 2; Articles 22, 26, 33 and 50."),

# ---------- 第四章 防止海域工程及海洋設施污染 ----------
(OP,"第20條",2,"海污法-海洋設施許可",
 "利用海洋設施從事探採油礦、輸送油、化學品或排放廢（污）水達公告規模者，應先完成何種程序？",
 ["應先檢具海洋污染防治計畫，載明海洋污染防治作業內容、海洋監測與應變措施及其他中央主管機關指定事項，報經中央主管機關許可後始得為之","應先檢具海洋污染防治計畫並載明作業內容與監測措施，報請目的事業主管機關備查後即得為之，無須報經中央主管機關許可即可開始作業","應先檢具環境影響評估書件及財務保證書，報請行政院核定後始得為之，海洋監測與應變措施得於作業開始後六個月內補行提出報備","應先取得港口管理機關核發之作業許可並繳納防治費，報請地方主管機關備查後始得為之，中央主管機關僅於事後進行查核及監督"],"a",
 "第20條第1項：利用海洋設施從事探採油礦、輸送油、化學品或排放廢（污）水達中央主管機關公告之規模者，應先檢具海洋污染防治計畫，載明海洋污染防治作業內容、海洋監測與應變措施及其他中央主管機關指定之事項，報經中央主管機關許可後始得為之。第42條對未經許可者處五年以下有期徒刑，得併科三十萬元以上三千萬元以下罰金。",
 "What must be done first before using marine facilities for oil exploration, oil or chemical transport, or wastewater discharge at the announced scale?",
 ["Submit a marine pollution control plan stating control operations, marine monitoring and response measures and other designated items, and obtain the central authority's permit","Submit a control plan stating operations and monitoring measures and file it with the industry authority, after which work may begin without any central permit","Submit environmental impact documents and a financial guarantee for Executive Yuan approval, with monitoring and response measures filed within six months after work starts","Obtain an operating permit from the port authority and pay the control fee, then file with the local authority, with the central authority only auditing afterwards"],
 "Article 20, paragraph 1; Article 42."),

(OP,"第20條",2,"海污法-監測與紀錄",
 "取得海洋設施作業許可者，於作業期間負有哪些持續性義務？",
 ["應持續執行海洋監測並定期向主管機關申報監測紀錄；其利用海洋設施探採油礦或輸送油時，並應製作探採或輸送紀錄","應持續執行海洋監測但無須申報監測紀錄；其利用海洋設施探採油礦或輸送油時，僅須於作業結束後彙整提出一次總結報告","應於發生污染事故時始執行海洋監測並申報紀錄；其利用海洋設施探採油礦或輸送油時，探採或輸送紀錄由目的事業主管機關製作","應委託港口管理機關代為執行海洋監測及申報紀錄；其利用海洋設施探採油礦或輸送油時，紀錄之製作得以航海日誌之記載代替之"],"a",
 "第20條第2項：取得許可者，應持續執行海洋監測，並定期向主管機關申報監測紀錄；其利用海洋設施探採油礦或輸送油時，應製作探採或輸送紀錄。第21條第2項並要求該等紀錄應依規定製作、申報並至少保存十年。第60條對未依規定監測、申報或製作紀錄者，處二十萬元以上一百萬元以下罰鍰。",
 "What ongoing duties bind a holder of a marine facility operating permit?",
 ["Continuously conduct marine monitoring and periodically report monitoring records; when exploring for oil or transporting oil, also prepare exploration or transport records","Continuously conduct monitoring but need not report records; when exploring for or transporting oil, only a single summary report after operations end is required","Conduct monitoring and report records only after a pollution incident; exploration or transport records are prepared by the relevant industry authority instead","Commission the port authority to conduct monitoring and reporting; exploration or transport records may be replaced by entries in the ship's logbook"],
 "Article 20, paragraph 2; Articles 21 and 60."),

(OP,"第21條",2,"海污法-禁止排洩",
 "廢（污）水、油、廢棄物、有害物質等污染物質排洩或傾倒於海洋，本法設有何種原則與例外？",
 ["原則不得排洩或傾倒於海洋；但經中央主管機關許可者，得將油、廢（污）水排放於海洋，其排放並應製作排放紀錄","原則不得排洩或傾倒於海洋；但經目的事業主管機關備查者，得將任何污染物質排放於海洋，且無須製作及保存排放紀錄","原則得排洩於海洋而無須許可；但經中央主管機關公告禁止之有害物質，於取得地方主管機關同意後始得排放並記錄","原則不得排洩或傾倒於海洋；但於專屬經濟海域及大陸礁層上覆水域範圍內，一律不受此限制，僅須事後申報排放數量"],"a",
 "第21條第1項：廢（污）水、油、廢棄物、有害物質或其他經中央主管機關指定公告之污染物質，不得排洩或傾倒於海洋；但經中央主管機關許可者，得將油、廢（污）水排放於海洋，其排放並應製作排放紀錄。第53條對違反第21條第1項本文者，處二十萬元以上二千萬元以下罰鍰，並得限期令其改善。",
 "What is the rule and exception for discharging wastewater, oil, waste or hazardous substances into the sea?",
 ["Such discharge or dumping is prohibited in principle; but with central approval oil and wastewater may be discharged into the sea, and discharge records must be prepared","Such discharge is prohibited in principle; but once filed with the industry authority any pollutant may be discharged, and no discharge records need be kept","Discharge is permitted in principle without any permit; only hazardous substances announced as prohibited require local authority consent before discharge and recording","Such discharge is prohibited in principle; but within the EEZ and waters above the continental shelf the ban does not apply and only later reporting of volumes is needed"],
 "Article 21, paragraph 1; Article 53."),

(OP,"第21條",2,"海污法-紀錄保存",
 "海洋設施之探採、輸送及排放紀錄應如何製作、申報及保存？排放許可辦法由誰訂定？",
 ["應依中央主管機關規定製作、申報並至少保存十年；排放油、廢（污）水於海洋許可之申請、條件、審查程序等辦法，由中央主管機關會商目的事業主管機關定之","應依中央主管機關規定製作、申報並至少保存三年；排放油、廢（污）水於海洋許可之申請、條件、審查程序等辦法，由目的事業主管機關逕行訂定並公告實施","應依港口管理機關規定製作並保存五年，無須向主管機關申報；排放油、廢（污）水於海洋許可之相關辦法，由行政院會商中央主管機關訂定後施行","應依國際公約規定製作、申報並永久保存；排放油、廢（污）水於海洋許可之申請、條件及審查程序，準用廢棄物清理法有關許可之規定辦理"],"a",
 "第21條第2項：第20條第2項後段及第21條第1項紀錄，應依中央主管機關規定製作、申報，並至少保存十年。第3項：排放油、廢（污）水於海洋許可之申請、條件、審查程序、廢止、排放許可之內容變更與設施停用備查及其他應遵行事項之辦法，由中央主管機關會商目的事業主管機關定之。第55條第6款對違反該辦法中內容變更或設施停用備查規定者處罰。",
 "How must exploration, transport and discharge records be kept, and who issues the discharge permit regulations?",
 ["They must be prepared and reported as prescribed by the central authority and kept for at least ten years; the permit regulations are issued by the central authority with the relevant industry authorities","They must be prepared and reported as prescribed by the central authority and kept for at least three years; the permit regulations are issued and announced by the relevant industry authority on its own","They must be prepared as prescribed by the port authority and kept five years without reporting; the permit regulations are set by the Executive Yuan with the central authority","They must be prepared and reported under international conventions and kept permanently; permit applications follow the Waste Disposal Act's permit provisions by analogy"],
 "Article 21, paragraphs 2 and 3; Article 55."),

(OP,"第22條",2,"海污法-海域工程應變",
 "從事海域工程或利用海洋設施致嚴重污染海洋或有嚴重污染之虞時，行為人應如何處理？",
 ["應即採取措施以防止、排除或減輕污染，並即通知主管機關及目的事業主管機關","應於發現污染後三十日內提出改善計畫，並通知目的事業主管機關即可","應立即停止全部工程並拆除海洋設施，無須通知主管機關即得自行處理","應通知承攬廠商及保險人處理，並於年度終了時彙報主管機關備查"],"a",
 "第22條第1項：從事海域工程或利用海洋設施致嚴重污染海洋或有嚴重污染海洋之虞時，應即採取措施以防止、排除或減輕污染，並即通知主管機關及目的事業主管機關。第2項並定明主管機關得命採取必要應變措施，必要時得逕行處理，費用由污染行為人負擔。第50條、第57條分別對未採取措施及未通知者處罰。",
 "What must an operator do where marine works or facilities seriously pollute or threaten to pollute the sea?",
 ["Immediately take measures to prevent, remove or mitigate the pollution and immediately notify the competent authority and the relevant industry authority","Submit an improvement plan within thirty days of discovering the pollution and notify only the relevant central industry authority of the incident","Immediately halt all works and dismantle the marine facility, handling matters alone without notifying any competent authority","Notify the contractor and the insurer to handle it and report to the competent authority for record at the end of the year"],
 "Article 22; Articles 50 and 57."),

# ---------- 第五章 防止海上處理廢棄物污染 ----------
(OP,"第23條",1,"海污法-海洋棄置許可",
 "從事海洋棄置者應踐行何種程序？相關許可辦法由誰訂定？",
 ["應向中央主管機關申請取得許可後始得為之；許可之申請、條件、審查程序及作業程序等辦法，由中央主管機關會商目的事業主管機關定之","應向地方主管機關申請取得許可後始得為之；許可之申請、條件、審查程序及作業程序等辦法，由地方主管機關逕行訂定並公告後實施","應向目的事業主管機關報請備查後始得為之；許可之申請、條件、審查程序及作業程序等辦法，由行政院會商中央主管機關定之","應向海岸巡防機關申請核發作業證明後始得為之；許可之申請、條件、審查程序及作業程序等辦法，由中央主管機關報請立法院審議"],"a",
 "第23條第1項：從事海洋棄置者，應向中央主管機關申請取得許可後始得為之。第2項：許可之申請、條件、審查程序、廢止、實施海洋棄置作業程序與許可內容變更及其他應遵行事項之辦法，由中央主管機關會商目的事業主管機關定之。第51條對未經許可棄置乙類或丙類物質，或違反該辦法中作業程序或許可內容規定者，處三十萬元以上三千萬元以下罰鍰。",
 "What procedure applies to ocean dumping, and who issues the permit regulations?",
 ["A permit must be obtained from the central competent authority first; the regulations on application, conditions, review and operating procedures are issued by the central authority with the industry authorities","A permit must be obtained from the local competent authority first; the regulations on application, conditions, review and dumping operating procedures are issued and announced by the local authorities","The matter need only be filed with the relevant industry authority for record; the regulations on application, conditions, review and procedures are issued by the Executive Yuan","An operating certificate must be obtained from the coast guard first; the regulations on application, conditions, review and procedures are submitted to the Legislative Yuan"],
 "Article 23; Article 51."),

(OP,"第24條",2,"海污法-棄置物質分類",
 "中央主管機關就棄置於海洋之物質如何分類？各類物質之管制方式為何？",
 ["依對海洋環境之影響公告為甲、乙、丙三類；甲類不得棄置於海洋，乙類之棄置時間數量及作業方式應取得許可，丙類於許可之期間及總量範圍內始得棄置","依對海洋環境之影響公告為甲、乙、丙三類；甲類須取得許可始得棄置，乙類不得棄置於海洋，丙類則得自由棄置而無須申請任何許可或報請備查","依物質之來源公告為甲、乙、丙三類；甲類與乙類均不得棄置於海洋，丙類之棄置時間、數量及作業方式應報請目的事業主管機關核准後辦理","依物質之毒性強弱公告為甲、乙、丙三類；三類物質均得棄置於海洋，惟甲類應加倍繳納海洋污染防治費，乙類與丙類則得減半繳納費用"],"a",
 "第24條第1項：中央主管機關應依物質棄置於海洋對海洋環境之影響，公告為甲類、乙類或丙類。第2項：甲類物質不得棄置於海洋；乙類物質棄置時間、數量及作業方式應取得中央主管機關許可；丙類物質於中央主管機關許可之期間及總量範圍內始得棄置。第40條對棄置甲類物質者處三年以下有期徒刑，得併科一百萬元以上五百萬元以下罰金。",
 "How are substances for ocean dumping classified, and how is each class controlled?",
 ["Announced as Class A, B or C by their impact on the marine environment; Class A may not be dumped, Class B requires a permit for timing, quantity and method, and Class C may be dumped only within the permitted period and total","Announced as Class A, B or C by impact; Class A may be dumped with a permit, Class B may not be dumped at all, and Class C may be dumped freely without any permit or filing","Announced as Class A, B or C by the source of the substance concerned; Classes A and B may not be dumped at sea at all, while Class C dumping timing, quantity and operating method need the relevant industry authority's approval","Announced as Class A, B or C by toxicity; all three classes may be dumped, but Class A pays a double control fee while Classes B and C pay half the fee"],
 "Article 24; Article 40."),

(OP,"第24條",2,"海污法-甲類物質",
 "違反規定將甲類物質棄置於海洋，或違反規定從事有害物質之海上焚化者，其刑責為何？",
 ["處三年以下有期徒刑，得併科新臺幣一百萬元以上五百萬元以下罰金；因而致嚴重污染海洋者，處七年以下有期徒刑，得併科三千萬元以上一億元以下罰金","處一年以下有期徒刑，得併科新臺幣三十萬元以上一百萬元以下罰金；因而致嚴重污染海洋者，處三年以下有期徒刑，得併科五百萬元以上三千萬元以下罰金","處五年以下有期徒刑，得併科新臺幣五百萬元以上一千萬元以下罰金；因而致嚴重污染海洋者，處十年以下有期徒刑，得併科一億元以上五億元以下罰金","處三年以下有期徒刑，得併科新臺幣一百萬元以上五百萬元以下罰金；因而致嚴重污染海洋者，改處拘役或科三千萬元以下罰金，且未遂犯一律不罰"],"a",
 "第40條第1項：違反第24條第2項前段棄置甲類物質於海洋，或違反第28條從事有害物質之海上焚化者，處三年以下有期徒刑，得併科新臺幣一百萬元以上五百萬元以下罰金。第2項：因而致嚴重污染海洋者，處七年以下有期徒刑，得併科三千萬元以上一億元以下罰金。第3項：第1項之未遂犯罰之。第45條對法人負責人或監督策劃人員犯罪者加重其刑至二分之一。",
 "What criminal liability attaches to dumping Class A substances at sea or incinerating hazardous substances at sea?",
 ["Up to three years' imprisonment, with a fine of NT$1 million to NT$5 million; where it causes serious marine pollution, up to seven years and a fine of NT$30 million to NT$100 million","Up to one year's imprisonment, with a fine of NT$300,000 to NT$1 million; where it causes serious marine pollution, up to three years and a fine of NT$5 million to NT$30 million","Up to five years' imprisonment, with a fine of NT$5 million to NT$10 million; where it causes serious marine pollution, up to ten years and a fine of NT$100 million to NT$500 million","Up to three years' imprisonment, with a fine of NT$1 million to NT$5 million; where it causes serious pollution, only detention or a fine up to NT$30 million, and attempts are never punished"],
 "Articles 24, 28, 40 and 45."),

(OP,"第25條",2,"海污法-棄置區域",
 "實施海洋棄置作業之區域如何決定？由誰依何種基準劃定公告？",
 ["應於中央主管機關指定之區域為之；該區域由中央主管機關依海域環境分類、海洋環境品質標準及海域水質狀況劃定公告","應於目的事業主管機關指定之區域為之；該區域由目的事業主管機關依作業便利性及航道距離劃定後報請中央主管機關備查","應於船舶所有人自行選定之海域為之；該區域僅須避開航道及漁場，並於作業前七日通知當地地方主管機關即可實施","應於行政院公告之專屬經濟海域內為之；該區域由海岸巡防機關依巡防勤務規劃及執行能量劃定，並每年檢討調整一次"],"a",
 "第25條第1項：實施海洋棄置作業，應於中央主管機關指定之區域為之。第2項：海洋棄置作業區域，由中央主管機關依海域環境分類、海洋環境品質標準及海域水質狀況，劃定公告之。第51條第3款對於非指定區域實施海洋棄置者，處三十萬元以上三千萬元以下罰鍰。",
 "Where must ocean dumping take place, and who designates the area on what basis?",
 ["In an area designated by the central competent authority, delimited and announced by it according to sea area classification, marine environment quality standards and water quality conditions","In an area designated by the relevant industry authority, delimited by it according to operational convenience and distance from shipping lanes and filed with the central competent authority","In waters chosen by the shipowner, which need only avoid shipping lanes and fishing grounds with seven days' prior notice to the local competent authority","Within the EEZ announced by the Executive Yuan, delimited by the coast guard according to patrol planning and capacity and reviewed once a year"],
 "Article 25, paragraphs 1 and 2; Article 51."),

(OP,"第25條",2,"海污法-棄置紀錄",
 "實施海洋棄置之船舶、航空器或海洋設施管理人，就作業紀錄負有何種義務？",
 ["應製作執行海洋棄置作業之紀錄，並定期將紀錄向中央主管機關申報及接受查核；受查核者不得規避、妨礙或拒絕","應製作執行海洋棄置作業之紀錄並自行保存備查，無須向中央主管機關申報，主管機關亦不得要求提供或進行查核","應由中央主管機關派員隨船製作作業紀錄，管理人僅負提供膳宿及交通工具之義務，並得拒絕主管機關之查核要求","應於每次作業完成後將紀錄送目的事業主管機關備查，中央主管機關僅得於發生污染事故時要求提供該紀錄查核"],"a",
 "第25條第3項：實施海洋棄置之船舶、航空器或海洋設施之管理人，應製作執行海洋棄置作業之紀錄，並定期將紀錄向中央主管機關申報及接受查核；受查核者不得規避、妨礙或拒絕。第58條對規避、妨礙或拒絕查核者處三十萬元以上一百五十萬元以下罰鍰，第60條第3款對未依規定記錄或申報者處二十萬元以上一百萬元以下罰鍰。",
 "What record duties bind the manager of a ship, aircraft or marine facility carrying out ocean dumping?",
 ["Prepare records of the dumping operations and periodically report them to the central authority and accept audits; the audited party may not evade, obstruct or refuse","Prepare and retain records on their own without reporting them to the central authority, which may neither demand them nor conduct any audit of the dumping operations","Have the central authority send staff aboard to prepare the records, with the manager only providing board and transport and free to refuse audits","Send records to the industry authority for record after each operation, with the central authority able to demand them only after a pollution incident"],
 "Article 25, paragraph 3; Articles 58 and 60."),

(OP,"第26條",1,"海污法-棄置應變",
 "從事海洋棄置作業致嚴重污染海洋或有嚴重污染之虞時，行為人及主管機關應如何處理？",
 ["行為人應即採取措施防止、排除或減輕污染並即通知主管機關及目的事業主管機關；主管機關得命其採取必要應變措施，必要時得逕行處理，費用由污染行為人負擔","行為人應於七日內提出污染改善報告並通知目的事業主管機關；主管機關僅得督導改善而不得逕行採取應變措施，其費用一律由海洋污染防治基金支應","行為人應立即停止棄置作業並將船舶駛回港口接受檢查；主管機關應通知目的事業主管機關代為處理，所生費用由該目的事業主管機關負擔","行為人應通知責任保險人及船級協會進行公證鑑定；主管機關於鑑定結果確定後始得命其採取應變措施，其費用依保險契約約定分擔"],"a",
 "第26條第1項：從事海洋棄置作業致嚴重污染海洋或有嚴重污染海洋之虞時，應即採取措施以防止、排除或減輕污染，並即通知主管機關及目的事業主管機關。第2項：主管機關得命污染行為人採取必要之應變措施，必要時得逕行採取應變措施、清除及處理，費用由污染行為人負擔。第50條、第57條分別對未採取措施及未通知者處罰。",
 "What must be done where ocean dumping seriously pollutes or threatens to pollute the sea?",
 ["The actor must immediately take measures to prevent, remove or mitigate and notify the competent and industry authorities; the authority may order response measures and act itself, with costs borne by the polluter","The actor must file an improvement report within seven days and notify the industry authority; the authority may only supervise and the costs are always met from the control fund","The actor must halt dumping and return the vessel to port for inspection; the authority must have the industry authority handle it, with that authority bearing the costs","The actor must notify the liability insurer and the classification society for a survey; the authority may order response measures only after the survey is concluded, with costs shared as per the insurance contract"],
 "Article 26; Articles 50 and 57."),

(OP,"第27條",2,"海污法-準用規定",
 "棄置船舶、航空器、海洋設施或其他人工構造物於海洋者，應如何適用本法規定？",
 ["準用第二十三條至第二十六條有關海洋棄置許可、物質分類、棄置區域及應變義務之規定","準用第十八條至第十九條有關陸上污染源排放許可及應變通知義務之相關規定","準用第二十九條至第三十二條有關船舶查驗、污染物收受及防制排洩之相關規定","準用第三十五條至第三十九條有關求償費用項目、責任保險及假扣押之相關規定"],"a",
 "第27條第1項：棄置船舶、航空器、海洋設施或其他人工構造物於海洋，準用第23條至第26條規定，即應取得中央主管機關許可、遵守物質分類管制、於指定區域為之並負應變通知義務。第51條、第57條、第58條、第60條並就準用情形分別定有罰則。",
 "How does the Act apply to dumping ships, aircraft, marine facilities or other artificial structures at sea?",
 ["Articles 23 to 26 on dumping permits, substance classification, designated areas and response duties apply mutatis mutandis to such dumping","Articles 18 to 19 on land-based source discharge permits and response and notification duties apply mutatis mutandis to such dumping","Articles 29 to 32 on ship inspection, pollutant reception facilities and discharge prevention measures apply mutatis mutandis to such dumping","Articles 35 to 39 on recoverable cost items, liability insurance and provisional attachment apply mutatis mutandis to such dumping"],
 "Article 27, paragraph 1."),

(OP,"第27條",2,"海污法-人工魚礁",
 "為漁業需要投設人工魚礁或其他漁業設施，應向何機關申請？其管理辦法由誰訂定？",
 ["應向中央漁業主管機關申請許可始得投設；其許可之申請、條件、審查程序、投設作業、設施檢查、管理及污染防治等辦法，由中央主管機關會同中央漁業及中央航政機關定之","應向中央主管機關申請許可始得投設；其許可之申請、條件、審查程序、投設作業、設施檢查、管理及污染防治等辦法，由中央漁業主管機關會同地方主管機關訂定","應向地方主管機關申請許可始得投設；其許可之申請、條件、審查程序、投設作業、設施檢查及管理等辦法，由各直轄市、縣（市）政府分別訂定自治規則","應向海岸巡防機關報備後即得投設；其投設作業、設施檢查、管理及污染防治等事項，由投設之漁會或漁業團體自行訂定作業規範並報請備查"],"a",
 "第27條第2項：為漁業需要，應向中央漁業主管機關申請許可，始得投設人工魚礁或其他漁業設施；其許可之申請、條件、審查程序、廢止投設作業、設施檢查、管理、污染防治及其他應遵行事項之辦法，由中央主管機關會同中央漁業及中央航政機關定之。第55條第7款對違反該辦法中投設作業、設施檢查、管理或污染防治規定者，處十萬元以上一千萬元以下罰鍰。",
 "Who permits the placement of artificial reefs for fishery purposes, and who issues the regulations?",
 ["A permit from the central fisheries authority is required; the regulations on application, conditions, review, placement, inspection, management and pollution control are issued by the central authority with the central fisheries and maritime authorities","A permit from the central competent authority is required; the regulations on application, conditions, review, placement, inspection, management and pollution control are issued by the central fisheries authority together with the local competent authorities","A permit from the local competent authority is required; the regulations on application, conditions, review, placement, inspection and management are made by each municipal and county government","Filing with the coast guard suffices; placement, inspection, management and pollution control matters are set by the fishermen's associations themselves and filed for record"],
 "Article 27, paragraph 2; Article 55."),

(OP,"第28條",1,"海污法-海上焚化",
 "本法對海上焚化之管制原則為何？",
 ["除因嚴重威脅人體健康、人身安全或海洋環境之緊急情況，經中央主管機關同意者外，不得從事海上焚化","除經目的事業主管機關備查並於指定海域為之者外，不得從事海上焚化，緊急情況亦不得例外從事焚化作業","原則得從事海上焚化，但應先取得地方主管機關許可並繳納防治費，且僅限於甲類物質不得焚化處理","原則得從事海上焚化，但應於作業前通知海岸巡防機關派員監督，並於作業後三十日內申報焚化紀錄"],"a",
 "第28條：除因嚴重威脅人體健康、人身安全或海洋環境之緊急情況，經中央主管機關同意者外，不得從事海上焚化。第4條第12款定明海上焚化指利用船舶或海洋設施焚化油或其他物質。違反者，若為有害物質之海上焚化依第40條處刑罰，其餘依第54條處十萬元以上一千萬元以下罰鍰。",
 "What is the Act's control principle on incineration at sea?",
 ["Incineration at sea is prohibited except in emergencies seriously threatening human health, personal safety or the marine environment, with the central authority's consent","Incineration at sea is prohibited unless filed with the industry authority and done in designated waters, with no exception even in emergency situations","Incineration at sea is generally allowed with a local authority permit and payment of the control fee, and only Class A substances may not be incinerated","Incineration at sea is generally allowed provided that the coast guard is notified to send supervisors beforehand and records are reported within thirty days afterwards"],
 "Article 28; Articles 40 and 54."),

# ---------- 第六章 防止船舶對海洋污染 ----------
(OP,"第29條",1,"海污法-船舶查驗",
 "港口管理機關或執行機關於必要時，得會同主管機關查驗船舶之哪些文件？",
 ["海洋污染防止證明書或證明文件、船上污染應急程序、操作手冊、油及貨紀錄簿、員工生活垃圾紀錄簿及其他經指定之文件","船舶所有權登記證書、船員名冊與薪資清冊、貨物運送契約、保險單正本及其他經港口管理機關指定之商業帳簿文件","船舶檢查證書、船員適任證書、旅客名單、船舶航行日誌及其他經航政機關依商港法規定所指定應備置之航行文件","海洋污染防治計畫、財務保證書、責任保險單、海洋棄置許可證及其他經中央主管機關依本法核發之各類許可文件"],"a",
 "第29條：港口管理機關或執行機關於必要時，得會同主管機關查驗船舶之海洋污染防止證明書或證明文件、船上污染應急程序、操作手冊、油、貨紀錄簿、員工生活垃圾紀錄簿及其他經各該機關指定之文件；受檢者不得規避、妨礙或拒絕。第58條對規避、妨礙或拒絕查驗者，處三十萬元以上一百五十萬元以下罰鍰並得按次處罰。",
 "Which ship documents may port or enforcement authorities inspect together with the competent authority?",
 ["Marine pollution prevention certificates or documents, shipboard pollution emergency procedures, operating manuals, oil and cargo record books, garbage record books and other designated documents","Ownership registration certificates, crew lists and payroll records, carriage contracts, original insurance policies and other commercial account books designated by the port authority","Ship inspection certificates, crew competency certificates, passenger lists, navigation logs and other navigation documents designated by maritime authorities under the Commercial Port Act","Marine pollution control plans, financial guarantees, liability insurance policies, ocean dumping permits and other permits issued by the central authority under this Act"],
 "Article 29; Article 58."),

(OP,"第30條",2,"海污法-船舶污染物",
 "船舶之廢（污）水、油、廢棄物或其他污染物質，除依規定得排洩於海洋者外，應如何處理？",
 ["應留存船上或排洩於岸上收受設施，並依廢棄物清理法等相關法規規定清除、處理","應於航行至領海範圍外之公海海域後排放，並將排放數量記錄於油貨紀錄簿內","應委由船舶所有人自行選定之民間廠商於海上處理，並於返港後檢附處理聯單","應交由海岸巡防機關派遣之勤務船艇接收，並由執行機關統一委託清除處理"],"a",
 "第30條第1項：船舶之廢（污）水、油、廢棄物或其他污染物質，除依規定得排洩於海洋者外，應留存船上、排洩於岸上收受設施，並依廢棄物清理法等相關法規規定清除、處理。第52條對違反者，總噸位四百以上一般船舶及一百五十以上油輪或化學品船處三十萬元以上三千萬元以下罰鍰，未達該規模者處三萬元以上三百萬元以下罰鍰。",
 "How must ship wastewater, oil, waste or other pollutants be handled unless discharge at sea is permitted?",
 ["They must be retained on board or discharged to shore reception facilities and cleaned up and treated under the Waste Disposal Act and related rules","They must be discharged on the high seas beyond the territorial sea, with the quantities discharged recorded in the oil and cargo record books","They must be treated at sea by a private contractor chosen by the shipowner, with manifests presented after returning to port","They must be handed to coast guard patrol vessels for collection, with the enforcement authority commissioning treatment centrally"],
 "Article 30, paragraph 1; Article 52."),

(OP,"第30條",2,"海污法-收受設施",
 "各類港口管理機關及事業機構就船舶污染物收受設施及紀錄申報，負有哪些義務？",
 ["應視管理需求設置收受設施並為必要處理，得收取處理費用，其收費標準報請目的事業主管機關核定；並應作成收受處理數量紀錄，於每年四月十五日前向中央主管機關申報前一年度紀錄","應視管理需求設置收受設施並為必要處理，但不得收取任何處理費用；並應作成收受處理數量紀錄，於每年十二月三十一日前向目的事業主管機關申報當年度之處理紀錄","應由中央主管機關統一設置收受設施並委託港口事業機構操作，處理費用由基金支應；港口機關僅須將數量紀錄保存備查，無須定期向任何機關申報","應要求船舶所有人自行設置收受設施並負擔費用；港口管理機關僅負監督之責，並於每年六月三十日前向行政院申報全國收受處理之總量統計資料"],"a",
 "第30條第2項：各類港口管理機關及事業機構應視管理需求設置前項污染物之收受設施及為必要之處理，並得收取處理費用；其收費標準由港口管理機關及事業機構擬訂，報請目的事業主管機關核定之。第3項：對所轄港口收受及處理污染物之數量，應分別作成紀錄及保存，並於每年四月十五日前，向中央主管機關申報前一年度紀錄。",
 "What duties do port authorities and enterprises have on reception facilities and reporting?",
 ["They must install reception facilities as needed and treat pollutants, may charge fees at rates approved by the industry authority, and must keep records and report the previous year's figures to the central authority by April 15 each year","They must install pollutant reception facilities as needed and treat pollutants but may charge no fees at all; they must keep records and report the current year's figures to the relevant industry authority by December 31 of each year","The central authority installs the facilities and commissions port enterprises to operate them with fund support; port authorities need only retain records and report to no agency","They must require shipowners to install their own reception facilities at their own cost; port authorities merely supervise and report national totals to the Executive Yuan by June 30"],
 "Article 30, paragraphs 2 and 3."),

(OP,"第31條",1,"海污法-船舶設備",
 "本法對船舶之防止污染設備及裝卸載運作業，設有何種要求？",
 ["船舶應設置防止污染設備並不得污染海洋；裝卸或載運油、化學品及其他可能造成海洋污染之貨物，應採取適當防制排洩措施","船舶應設置防止污染設備但得於公海海域關閉使用；裝卸或載運油及化學品時，僅須通知港口管理機關派員在場監督即可","船舶得視航線需要決定是否設置防止污染設備；裝卸或載運油、化學品時，應由託運人負責採取適當之防制排洩措施","船舶應設置防止污染設備並每五年檢查一次；裝卸或載運油、化學品等貨物之防制排洩措施，由船級協會逕行認定合格"],"a",
 "第31條第1項：船舶應設置防止污染設備，並不得污染海洋。第2項：船舶裝卸或載運油、化學品及其他可能造成海洋污染之貨物，應採取適當防制排洩措施。第48條對違反第31條第2項者，依船舶規模處罰：總噸位四百以上一般船舶及一百五十以上油輪或化學品船處一百萬元以上三千萬元以下罰鍰，未達該規模者處三十萬元以上三百萬元以下罰鍰。",
 "What does the Act require of ships' pollution prevention equipment and cargo handling?",
 ["Ships must install pollution prevention equipment and must not pollute the sea; when loading or carrying oil, chemicals or other potentially polluting cargo, proper discharge prevention measures must be taken","Ships must install pollution prevention equipment but may switch it off on the high seas; when loading or carrying oil and chemicals, they need only ask the port authority to send a supervisor on site","Ships may decide whether to install prevention equipment according to their route; when loading or carrying oil and chemicals, the shipper takes the discharge prevention measures","Ships must install prevention equipment inspected every five years; discharge prevention measures for oil and chemical cargo are certified by the classification society"],
 "Article 31; Article 48."),

(OP,"第32條",2,"海污法-船舶施工",
 "船舶之建造、修理、拆解、打撈、清艙及船身清洗致污染海洋或有污染之虞者，應採取哪些措施？",
 ["於施工區域周圍水面設置適當攔除浮油設備；於施工區內備置適當廢油、廢（污）水、廢棄物及有害物質收受設施；防止該等物質排洩於海洋；及其他經中央主管機關指定之措施","於施工區域周圍水面設置警示浮標及照明設備；於施工區內備置消防與救生器材；防止噪音及粉塵逸散至鄰近水域；及其他經港口管理機關依商港法所指定之安全措施","於施工前完成環境影響評估並取得許可；於施工區內設置水質自動監測儀器；每日將監測數據上傳中央主管機關；及其他經目的事業主管機關指定之監測管理措施","於施工區域投保足額責任保險並提供財務保證書；於施工區內備置油污清除藥劑；委託海岸巡防機關派艇警戒；及其他經行政院公告之緊急應變準備措施"],"a",
 "第32條：船舶之建造、修理、拆解、打撈、清艙及船身清洗，致污染海洋或有污染海洋之虞者，應採取下列措施並清除污染物質：一、於施工區域周圍水面設置適當之攔除浮油設備。二、於施工區內備置適當廢油、廢（污）水、廢棄物及有害物質收受設施。三、防止油、廢油、廢（污）水、廢棄物、殘餘物及有害物質排洩於海洋。四、其他經中央主管機關指定之措施。第48條依船舶規模定其罰鍰額度。",
 "What measures are required for ship building, repair, scrapping, salvage, tank cleaning and hull washing that may pollute the sea?",
 ["Install suitable oil boom equipment on the water around the work area; provide reception facilities for waste oil, wastewater, waste and hazardous substances inside it; prevent such matter from being discharged to sea; and other designated measures","Install warning buoys and lighting around the work area; provide firefighting and lifesaving gear inside it; prevent noise and dust from spreading to nearby waters; and other safety measures designated by the port management authorities concerned","Complete an environmental impact assessment and obtain a permit before work; install automatic water quality monitors in the work area; upload data daily to the central authority; and other monitoring measures designated","Take out adequate liability insurance and provide a financial guarantee; stock oil dispersants in the work area; ask the coast guard to send patrol boats; and other emergency preparedness measures announced"],
 "Article 32; Article 48."),

(OP,"第32條",2,"海污法-船舶施工罰則",
 "違反第三十一條第二項或第三十二條規定者，其罰鍰額度依何標準區分？",
 ["依船舶規模區分：總噸位四百以上之一般船舶及一百五十以上之油輪或化學品船處一百萬元以上三千萬元以下；未達該規模者處三十萬元以上三百萬元以下","依污染面積區分：污染範圍達一平方公里以上者處一百萬元以上三千萬元以下；未達一平方公里者處三十萬元以上三百萬元以下罰鍰並得按次處罰","依船齡區分：船齡二十年以上之船舶處一百萬元以上三千萬元以下；船齡未達二十年之船舶處三十萬元以上三百萬元以下罰鍰並得令其停工","依船籍區分：外國籍船舶處一百萬元以上三千萬元以下；本國籍船舶處三十萬元以上三百萬元以下罰鍰，並得限期令其改善及按次處罰"],"a",
 "第48條：違反第31條第2項或第32條規定者，依其船舶規模處罰鍰，並得限期令其改善，屆期未改善者得按次處罰，情節重大者得令其停工：一、總噸位四百以上之一般船舶及一百五十以上之油輪或化學品船，處新臺幣一百萬元以上三千萬元以下。二、未達前款規模之船舶，處新臺幣三十萬元以上三百萬元以下。第44條並對不遵行停工命令者處二年以下有期徒刑。",
 "On what basis are fines differentiated for violations of Article 31(2) or Article 32?",
 ["By ship size: general ships of 400 GT or more and tankers or chemical carriers of 150 GT or more face NT$1 million to NT$30 million; smaller ships face NT$300,000 to NT$3 million","By polluted area: pollution covering one square kilometer or more faces NT$1 million to NT$30 million; less than that faces NT$300,000 to NT$3 million with repeat penalties","By ship age: ships twenty years old or more face NT$1 million to NT$30 million; ships under twenty years face NT$300,000 to NT$3 million and may be ordered to stop work","By flag: foreign ships face NT$1 million to NT$30 million; domestic ships face NT$300,000 to NT$3 million with orders to improve and repeat penalties"],
 "Article 48; Article 44."),

(OP,"第33條",2,"海污法-海難應變",
 "因海難或其他意外事件致污染海洋或有污染之虞時，何人應採取措施並通知哪些機關？",
 ["船長及船舶所有人應即採取措施防止、排除或減輕污染，並即通知航政機關、港口管理機關、事業機構及直轄市、縣（市）主管機關","船長應即採取措施防止污染，並僅須通知船舶所有人及責任保險人，由其代為通報航政機關與港口管理機關等相關單位","船舶所有人應於事故發生後七日內採取措施，並通知中央主管機關及海岸巡防機關，船長於此期間內無任何通知義務","貨物託運人及船舶代理業者應即採取措施，並通知航政機關與地方主管機關，船長及船舶所有人僅負配合調查之義務"],"a",
 "第33條第1項：因發生海難或其他意外事件，致污染海洋或有污染海洋之虞時，船長及船舶所有人應即採取措施以防止、排除或減輕污染，並即通知航政機關、港口管理機關、事業機構及直轄市、縣（市）主管機關。第4條第8款定明海難之意義。第57條對未依規定通知者，處三十萬元以上一百五十萬元以下罰鍰。",
 "Who must act and whom must they notify when a maritime peril or accident pollutes or threatens to pollute the sea?",
 ["The master and the shipowner must immediately take measures to prevent, remove or mitigate the pollution and immediately notify the maritime, port, enterprise and municipal or county authorities","The master must take measures and need only notify the shipowner and the liability insurer, who then relay the information to the maritime and port authorities","The shipowner must act within seven days of the incident and notify the central authority and the coast guard, the master owing no notification duty in that period","The cargo shipper and the shipping agent must act and notify the maritime and local competent authorities, the master and shipowner owing only a duty to assist with the later investigation"],
 "Article 33, paragraph 1; Article 57."),

(OP,"第33條",2,"海污法-海難費用",
 "海難污染事件中，主管機關得為何種命令？應變清除處理費用由何人負擔？",
 ["主管機關得命船長及船舶所有人採取必要之應變措施，必要時並得逕行採取應變措施、清除及處理，所生費用由該船舶所有人負擔","主管機關得命船長採取必要之應變措施，但不得逕行處理；所生費用由船長個人與船員連帶負擔，船舶所有人不負任何費用責任","主管機關得命港口管理機關代為採取應變措施，並先由海洋污染防治基金支應費用，事後不得再向船舶所有人請求歸墊","主管機關得命責任保險人逕行採取應變措施，所生費用於保險金額範圍內由保險人負擔，超過部分由中央政府預算支應"],"a",
 "第33條第2項：主管機關得命船長及船舶所有人採取必要之應變措施，必要時，主管機關並得逕行採取應變措施、清除及處理；其因應變措施、清除及處理所生費用，由該船舶所有人負擔。第36條第1項並定明船舶對海洋污染產生之損害，船舶所有人應負賠償責任；第39條定明該等求償權優於抵押權、留置權及一般債權。",
 "In a maritime peril pollution case, what may the authority order and who bears the response costs?",
 ["It may order the master and shipowner to take necessary response measures and where necessary act itself, with the resulting response, removal and treatment costs borne by the shipowner","It may order the master to take measures but may not act itself; the costs fall jointly on the master and crew personally, with the shipowner bearing none","It may order the port authority to act on its behalf with the control fund advancing the costs, and no reimbursement may later be sought from the shipowner","It may order the liability insurer to take response action directly, with costs borne by the insurer up to the sum insured and the excess met from the central government budget"],
 "Article 33, paragraph 2; Articles 36 and 39."),

(OP,"第34條",2,"海污法-外國船舶管制",
 "未在我國依法設立分公司之外國籍船舶運送業，其船舶違反本法經處罰鍰者，主管機關得為何種處置？",
 ["於繳清罰鍰或提供足額擔保前，得命該船舶泊靠我國港口，禁止其航行、開航或要求移航；開航後復駛入我國領海者亦同","於繳清罰鍰前，得逕行扣押該船舶並拍賣抵充罰鍰；船舶開航後復駛入我國領海者，不得再為任何禁止航行之處置","於繳清罰鍰或提供足額擔保前，得撤銷該船舶之航行證書並註銷其船籍登記；船舶開航後即不得再要求其返航泊靠","於繳清罰鍰前，得命該船舶駛離我國領海並禁止其再度進入；船舶如已開航，應由外交部循外交途徑向船旗國求償"],"a",
 "第34條第1項：未在我國依法設立分公司之外國籍船舶運送業，其船舶違反本法而經處罰鍰者，於繳清罰鍰或提供足額擔保前，主管機關得命該船舶泊靠我國港口，禁止其航行、開航或要求移航；開航後復駛入我國領海者亦同。第2項：港口管理機關、事業機構應協助規劃船席、泊靠船席及限制該船舶出港，必要時主管機關得要求執行機關強制其泊靠至指定席位。第38條就損害賠償責任設有類似規定，並得限制船舶所有人及重要船員離境。",
 "What may the authority do to a fined foreign ship whose operator has no branch established in the ROC?",
 ["Before the fine is paid or adequate security provided, it may order the ship to berth in an ROC port and forbid it to sail, depart or require it to shift berth; the same applies if it re-enters ROC waters after departure","Before the fine is paid, it may seize and auction the ship to satisfy the fine; once the ship has departed, no further order forbidding navigation may be issued against it","Before the fine is paid or security provided, it may revoke the ship's navigation certificate and cancel its registry; once departed, the ship may not be recalled to berth","Before the fine is paid, it may order the ship to leave ROC territorial waters and permanently bar its return; if it has already sailed, the foreign ministry instead pursues the flag state through diplomatic channels"],
 "Article 34; Article 38."),
]
